  { id: 'gemini-2.5-flash-lite-latest', name: 'Gemini 2.5 Flash Lite (Standard)', provider: 'gemini', hasVision: true },
  { id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash (Latest)', provider: 'gemini', hasVision: true },
  { id: 'gemini-3-pro-preview', name: 'Gemini 3 Pro (High Quality)', provider: 'gemini', hasVision: true },
  { id: 'gemini-2.5-flash-latest', name: 'Gemini 2.5 Flash', provider: 'gemini', hasVision: true },
  { id: 'pixtral-12b-2409', name: 'Pixtral 12B Vision', provider: 'mistral', hasVision: true },
  { id: 'llama-3.2-11b-vision-preview', name: 'Llama 4 Scout Fast (Vision Capable)', provider: 'groq', hasVision: true },
];

export const DEFAULT_SETTINGS: Settings = {
  apiKeys: {
    gemini: '',
    groq: '',
    mistral: '',
  },
  preferredModel: 'gemini-3-flash-preview',
  customInstruction: '',
  prefixes: [],
  suffixes: [],
