import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage } from '../types';

// Helper to convert File to base64
const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = reader.result as string;
      resolve(base64String.split(',')[1]);
    };
    reader.onerror = error => reject(error);
  });
};

export class AIService {
  private static async geminiGenerate(
    modelId: string, 
    prompt: string, 
    image?: PromptForgeImage,
    systemInstruction?: string
  ) {
    // Fix: Initialize GoogleGenAI exclusively with process.env.API_KEY as per guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const parts: any[] = [{ text: prompt }];
    if (image) {
      const base64Data = await fileToBase64(image.file);
      parts.unshift({
        inlineData: {
          mimeType: image.file.type,
          data: base64Data
        }
      });
    }

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });

    // Fix: Correctly access the .text property of GenerateContentResponse (not a method)
    return response.text;
  }

  // Generic fetch for Groq/Mistral (Mocked logic as these typically require standard fetch requests)
  private static async providerGenerate(
    provider: Provider,
    modelId: string,
    apiKey: string,
    prompt: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`
        },
        body: JSON.stringify({
          model: modelId,
          messages: [
            ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
            { role: 'user', content: prompt }
          ]
        })
      });

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.error?.message || `API Error ${response.status}`);
      }

      const data = await response.json();
      return data.choices[0].message.content;
    } catch (e: any) {
      throw new Error(`${provider} failed: ${e.message}`);
    }
  }

  public static async generatePromptFromImage(
    image: PromptForgeImage,
    settings: any,
    model: Model
  ) {
    const systemPrompt = `You are a professional stock photography prompt engineer. 
    Analyze the provided image and extract a rich, detailed, stock-ready prompt.
    Include composition, lighting, color palette, camera lens/angle, subject details, textures, background.
    Output: ONE CLEAR PARAGRAPH. No bullet lists. No symbols. Professional language. English only.
    ${settings.customInstruction ? `\nGlobal Instruction: ${settings.customInstruction}` : ''}`;

    const userPrompt = "Describe this image in detail for re-creation in an AI image generator.";

    if (model.provider === 'gemini') {
      // Fix: Removed passing settings.apiKeys.gemini as key is handled internally via environment
      return await this.geminiGenerate(model.id, userPrompt, image, systemPrompt);
    } else {
      throw new Error(`Vision generation not yet implemented for ${model.provider}`);
    }
  }

  public static async refinePrompt(
    input: string,
    settings: any,
    model: Model
  ) {
    const systemPrompt = `Refine the user's prompt into a powerful, professional English prompt paragraph.
    Clean grammar, remove extra characters, translate to English if needed. 
    Output should be one powerful paragraph. No bullets.
    ${settings.customInstruction ? `\nGlobal Instruction: ${settings.customInstruction}` : ''}`;

    if (model.provider === 'gemini') {
      // Fix: Removed passing settings.apiKeys.gemini
      return await this.geminiGenerate(model.id, input, undefined, systemPrompt);
    } else {
      return await this.providerGenerate(model.provider, model.id, settings.apiKeys[model.provider as keyof typeof settings.apiKeys], input, systemPrompt);
    }
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    if (!apiKey) return [];

    try {
      const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';
      const response = await fetch(`${baseUrl}/models`, {
        headers: { 'Authorization': `Bearer ${apiKey}` }
      });
      const data = await response.json();
      return data.data.map((m: any) => ({
        id: m.id,
        name: m.id.split(':').pop() || m.id,
        provider,
        hasVision: m.id.toLowerCase().includes('vision') || m.id.toLowerCase().includes('pixtral')
      }));
    } catch (e) {
      console.error(`Failed to fetch ${provider} models`, e);
      return [];
    }
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Plus, 
  Trash2, 
  Download, 
  Settings as SettingsIcon, 
  RotateCcw, 
  MessageSquare, 
  Share2, 
  ChevronDown, 
  X, 
  Copy, 
  Check, 
  AlertCircle,
  ExternalLink,
  ChevronRight
} from 'lucide-react';
import { 
  PromptForgeImage, 
  Settings, 
  Model, 
  Provider,
  CommunityLink
} from './types';
import { 
  INITIAL_MODELS, 
  DEFAULT_SETTINGS, 
  LOGO_SVG 
} from './constants';
import { AIService } from './services/aiService';

export default function App() {
  // --- State ---
  const [images, setImages] = useState<PromptForgeImage[]>([]);
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('prompt_forge_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });
  const [models, setModels] = useState<Model[]>(INITIAL_MODELS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [activeModal, setActiveModal] = useState<'hub' | 'settings' | 'privacy' | 'terms' | 'faq' | null>(null);
  const [refineInput, setRefineInput] = useState('');
  const [refineOutput, setRefineOutput] = useState('');
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'error' | 'warning' } | null>(null);
  const [usageLimitError, setUsageLimitError] = useState<{ modelId: string; provider: Provider } | null>(null);

  // --- Effects ---
  useEffect(() => {
    const updateModels = async () => {
      const groqModels = await AIService.fetchModels('groq', settings.apiKeys.groq);
      const mistralModels = await AIService.fetchModels('mistral', settings.apiKeys.mistral);

      setModels(prev => {
        const base = prev.filter(m => m.provider === 'gemini');
        const uniqueIds = new Set(base.map(m => m.id));
        const filteredGroq = groqModels.filter(m => !uniqueIds.has(m.id));
        const filteredMistral = mistralModels.filter(m => !uniqueIds.has(m.id));
        return [...base, ...filteredGroq, ...filteredMistral];
      });
    };
    updateModels();
  }, [settings.apiKeys.groq, settings.apiKeys.mistral]);

  // --- Helpers ---
  const showNotification = (message: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const saveSettings = () => {
    localStorage.setItem('prompt_forge_settings', JSON.stringify(settings));
    showNotification("Settings saved successfully.");
  };

  const handleClearData = () => {
    if (window.confirm("Clear all uploaded images and generated prompts? This cannot be undone.")) {
      setImages([]);
      setRefineInput('');
      setRefineOutput('');
      showNotification("Data cleared.", "warning");
    }
  };

  // Fix: Improved file upload handler to support both ChangeEvent and DragEvent with correct typing
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent<HTMLDivElement>) => {
    let fileList: FileList | null = null;
    if ('dataTransfer' in e) {
      fileList = e.dataTransfer.files;
    } else if (e.target.files) {
      fileList = e.target.files;
    }

    if (!fileList) return;
    const files = Array.from(fileList);

    // Fix: Explicitly type file as File to avoid 'unknown' type errors and URL.createObjectURL issues (Errors on lines 89 and 92)
    const newImages: PromptForgeImage[] = files.map((file: File) => ({
      id: Math.random().toString(36).substring(2, 11),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending',
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const removeImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
  };

  const generatePrompts = async () => {
    if (!images.length) return showNotification("Please upload some images first.", "error");

    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const isGemini = activeModel.provider === 'gemini';

    // Fix: Updated API key check to account for environment-managed Gemini key
    const apiKey = isGemini ? process.env.API_KEY : (settings.apiKeys as any)[activeModel.provider];

    if (!apiKey) {
      return showNotification(isGemini ? "Gemini API key is missing from environment." : `Please provide an API key for ${activeModel.provider} in settings.`, "error");
    }

    setIsGenerating(true);
    setGenerationProgress(0);
    setUsageLimitError(null);

    const updatedImages = [...images];
    for (let i = 0; i < updatedImages.length; i++) {
      if (updatedImages[i].status === 'completed') continue;

      try {
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'processing' } : img));

        let promptResult = await AIService.generatePromptFromImage(updatedImages[i], settings, activeModel);

        const prefixes = settings.prefixes.slice(0, settings.prefixCount).join(' ');
        const suffixes = settings.suffixes.slice(0, settings.suffixCount).join(' ');
        const fullPrompt = `${prefixes} ${promptResult} ${suffixes}`.trim().replace(/\s+/g, ' ');

        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'completed', prompt: fullPrompt } : img));
      } catch (error: any) {
        if (error.message.includes('rate limit') || error.message.includes('429')) {
          setUsageLimitError({ modelId: activeModel.id, provider: activeModel.provider });
          setIsGenerating(false);
          return;
        }
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'error', error: error.message } : img));
      }
      setGenerationProgress(((i + 1) / updatedImages.length) * 100);
    }
    setIsGenerating(false);
  };

  const refinePromptAction = async () => {
    if (!refineInput) return;
    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const isGemini = activeModel.provider === 'gemini';
    const apiKey = isGemini ? process.env.API_KEY : (settings.apiKeys as any)[activeModel.provider];

    if (!apiKey) {
      return showNotification(isGemini ? "Gemini API key is missing from environment." : `Please provide an API key for ${activeModel.provider} in settings.`, "error");
    }

    try {
      setIsGenerating(true);
      const refined = await AIService.refinePrompt(refineInput, settings, activeModel);
      setRefineOutput(refined);
    } catch (error: any) {
      showNotification(`Refinement failed: ${error.message}`, "error");
    } finally {
      setIsGenerating(false);
    }
  };

  const exportCSV = () => {
    const header = "SL No., Image Filename, Prompt\n";
    const rows = images.map((img, i) => `${i + 1}, "${img.file.name}", "${img.prompt?.replace(/"/g, '""') || ''}"`).join('\n');
    const blob = new Blob([header + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `promptforge_prompts_${new Date().toISOString().replace(/[:T]/g, '_').split('.')[0]}.csv`;
    a.click();
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    showNotification("Copied to clipboard!");
  };

  return (
    <div className={`min-h-screen transition-colors ${settings.theme === 'light' ? 'bg-slate-50 text-slate-900' : 'bg-slate-950 text-white'}`}>
      <div className="fixed inset-0 pointer-events-none opacity-20 gradient-bg -z-10" />

      <header className="sticky top-0 z-40 backdrop-blur-lg border-b border-white/10 px-6 py-4">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center">
            {LOGO_SVG}
            <div>
              <h1 className="text-2xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-violet-400 to-fuchsia-400">
                Prompt Forge
              </h1>
              <p className="text-xs text-slate-400 font-medium">Make better prompts for real result</p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            <button 
              onClick={() => setActiveModal('hub')}
              className="px-4 py-2 rounded-full glass-card hover:bg-white/10 transition flex items-center text-sm font-medium"
            >
              <Share2 size={16} className="mr-2" />
              Community Hub
            </button>
            <button 
              onClick={() => setActiveModal('settings')}
              className="p-2 rounded-full glass-card hover:bg-white/10 transition"
            >
              <SettingsIcon size={20} />
            </button>
          </div>
        </div>
      </header>

      {usageLimitError && (
        <div className="bg-amber-500/20 border-b border-amber-500/30 px-6 py-3 text-center">
          <p className="text-amber-300 text-sm font-medium flex items-center justify-center">
            <AlertCircle size={16} className="mr-2" />
            Usage limit reached for {usageLimitError.modelId}. Change model to continue.
            <button 
              onClick={() => setActiveModal('settings')}
              className="ml-4 underline hover:text-white"
            >
              Switch Model
            </button>
          </p>
        </div>
      )}

      {notification && (
        <div className={`fixed bottom-24 right-6 z-50 px-6 py-3 rounded-2xl shadow-2xl flex items-center border animate-bounce ${
          notification.type === 'success' ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-400' :
          notification.type === 'error' ? 'bg-rose-500/20 border-rose-500/30 text-rose-400' :
          'bg-amber-500/20 border-amber-500/30 text-amber-400'
        }`}>
          {notification.type === 'success' ? <Check size={18} className="mr-2" /> : <AlertCircle size={18} className="mr-2" />}
          {notification.message}
        </div>
      )}

      <main className="max-w-5xl mx-auto px-6 py-12 space-y-12 pb-32">
        <section className="space-y-6">
          <div className="flex items-center justify-between">
            <h2 className="text-2xl font-bold flex items-center">
              <span className="w-1.5 h-8 bg-violet-500 rounded-full mr-4" />
              Image to Prompt Generator
            </h2>
            <div className="flex space-x-2">
              {images.length > 0 && (
                <button 
                  onClick={handleClearData}
                  className="px-4 py-2 rounded-xl text-sm font-medium text-rose-400 hover:bg-rose-500/10 transition flex items-center"
                >
                  <Trash2 size={16} className="mr-2" />
                  Clear Data
                </button>
              )}
            </div>
          </div>

          <div 
            className="relative group p-12 border-2 border-dashed border-white/20 rounded-3xl text-center glass-card hover:border-violet-500/50 transition-all cursor-pointer"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => { e.preventDefault(); handleFileUpload(e); }}
          >
            <input 
              type="file" 
              multiple 
              className="absolute inset-0 opacity-0 cursor-pointer" 
              onChange={handleFileUpload} 
              accept="image/png, image/jpeg"
            />
            <div className="space-y-4">
              <div className="w-20 h-20 bg-violet-500/10 rounded-full flex items-center justify-center mx-auto group-hover:scale-110 transition-transform">
                <Plus size={40} className="text-violet-400" />
              </div>
              <p className="text-xl font-medium text-slate-300">Drag & drop or click to add images</p>
              <p className="text-sm text-slate-500">Supports JPG, PNG (Bulk upload enabled)</p>
            </div>
          </div>

          {images.length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              {images.map((img) => (
                <div key={img.id} className="glass-card rounded-2xl overflow-hidden group border border-white/5 hover:border-white/20 transition-all">
                  <div className="aspect-square relative overflow-hidden bg-slate-900">
                    <img src={img.previewUrl} alt="Upload" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                    <button 
                      onClick={() => removeImage(img.id)}
                      className="absolute top-3 right-3 p-2 bg-black/50 text-white rounded-full opacity-0 group-hover:opacity-100 transition backdrop-blur-md"
                    >
                      <X size={16} />
                    </button>
                    {img.status === 'processing' && (
                      <div className="absolute inset-0 bg-black/40 flex items-center justify-center backdrop-blur-sm">
                        <div className="w-12 h-12 border-4 border-violet-500 border-t-transparent rounded-full animate-spin" />
                      </div>
                    )}
                  </div>
                  <div className="p-4 space-y-3">
                    <p className="text-xs text-slate-400 truncate">{img.file.name}</p>
                    {img.prompt && (
                      <div className="space-y-2">
                        <p className="text-sm text-slate-300 line-clamp-4 leading-relaxed bg-white/5 p-3 rounded-xl">
                          {img.prompt}
                        </p>
                        <button 
                          onClick={() => copyToClipboard(img.prompt!)}
                          className="w-full py-2 flex items-center justify-center text-xs font-medium text-violet-400 hover:bg-violet-500/10 rounded-lg transition"
                        >
                          <Copy size={12} className="mr-2" />
                          Copy Prompt
                        </button>
                      </div>
                    )}
                    {img.status === 'error' && <p className="text-xs text-rose-400">Error: {img.error}</p>}
                  </div>
                </div>
              ))}
            </div>
          )}

          {isGenerating && (
            <div className="space-y-2">
              <div className="flex justify-between text-xs font-medium text-slate-400 px-1">
                <span>Processing Batch...</span>
                <span>{Math.round(generationProgress)}%</span>
              </div>
              <div className="w-full h-3 bg-white/5 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-gradient-to-r from-violet-500 to-fuchsia-500 transition-all duration-500" 
                  style={{ width: `${generationProgress}%` }}
                />
              </div>
            </div>
          )}

          <div className="flex flex-col sm:flex-row gap-4 pt-4">
            <button 
              onClick={generatePrompts}
              disabled={isGenerating || images.length === 0}
              className={`flex-1 py-4 px-8 rounded-2xl font-bold text-lg shadow-xl shadow-violet-500/20 transition-all active:scale-95 flex items-center justify-center ${
                isGenerating || images.length === 0 
                  ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                  : 'bg-gradient-to-r from-violet-600 to-fuchsia-600 hover:from-violet-500 hover:to-fuchsia-500 text-white'
              }`}
            >
              {isGenerating ? (
                <>
                  <RotateCcw className="mr-2 animate-spin" size={24} />
                  Generating...
                </>
              ) : (
                usageLimitError ? 'Regenerate' : 'Generate Prompts'
              )}
            </button>
            {images.some(img => img.status === 'completed') && (
              <button 
                onClick={exportCSV}
                className="py-4 px-8 rounded-2xl bg-slate-800 hover:bg-slate-700 text-white font-bold text-lg transition flex items-center justify-center border border-white/10"
              >
                <Download className="mr-2" size={24} />
                Download CSV
              </button>
            )}
          </div>
        </section>

        <hr className="border-white/5" />

        <section className="space-y-6">
          <h2 className="text-2xl font-bold flex items-center">
            <span className="w-1.5 h-8 bg-fuchsia-500 rounded-full mr-4" />
            Refine your prompt like a prompt engineer
          </h2>
          <div className="glass-card rounded-3xl p-8 space-y-4">
            <textarea 
              value={refineInput}
              onChange={(e) => setRefineInput(e.target.value)}
              placeholder="Paste any messy prompt or description in any language here..."
              className="w-full h-40 bg-white/5 rounded-2xl p-6 text-slate-200 placeholder-slate-500 border border-white/10 focus:border-violet-500 focus:ring-1 focus:ring-violet-500 outline-none transition-all resize-none"
            />
            <button 
              onClick={refinePromptAction}
              disabled={isGenerating || !refineInput}
              className="w-full py-4 bg-fuchsia-600 hover:bg-fuchsia-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold rounded-2xl transition flex items-center justify-center shadow-lg shadow-fuchsia-500/20"
            >
              {isGenerating ? <RotateCcw size={20} className="mr-2 animate-spin" /> : <MessageSquare size={20} className="mr-2" />}
              Refine Prompt
            </button>

            {refineOutput && (
              <div className="mt-8 animate-in fade-in zoom-in-95 duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Engineered Result</span>
                  <button 
                    onClick={() => copyToClipboard(refineOutput)}
                    className="p-2 hover:bg-white/10 rounded-lg text-slate-400 transition"
                  >
                    <Copy size={16} />
                  </button>
                </div>
                <div className="p-6 bg-gradient-to-br from-violet-500/10 to-fuchsia-500/10 border border-white/10 rounded-2xl relative">
                  <p className="text-lg leading-relaxed text-slate-200 italic">{refineOutput}</p>
                </div>
              </div>
            )}
          </div>
        </section>

        <section className="grid md:grid-cols-2 gap-8">
          <div className="space-y-6">
            <h2 className="text-xl font-bold flex items-center">
              <span className="w-1.5 h-6 bg-indigo-500 rounded-full mr-3" />
              Prefix Manager
            </h2>
            <div className="glass-card p-6 rounded-2xl space-y-4">
              <input 
                type="text"
                placeholder="Add new prefix..."
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    const val = (e.target as HTMLInputElement).value.trim();
                    if (val && !settings.prefixes.includes(val)) {
                      setSettings({ ...settings, prefixes: [...settings.prefixes, val] });
                      (e.target as HTMLInputElement).value = '';
                    } else if (settings.prefixes.includes(val)) {
                      showNotification("Prefix already exists.", "warning");
                    }
                  }
                }}
                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm outline-none focus:border-indigo-500 transition"
              />
              <div className="flex items-center justify-between text-xs text-slate-500">
                <span>Apply first {settings.prefixCount} prefixes</span>
                <input 
                  type="range" min="0" max={settings.prefixes.length} value={settings.prefixCount}
                  onChange={(e) => setSettings({ ...settings, prefixCount: parseInt(e.target.value) })}
                  className="ml-4 flex-1 h-1.5 bg-white/10 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                />
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.prefixes.map((p, i) => (
                  <span key={i} className={`px-3 py-1 rounded-full text-xs flex items-center transition ${i < settings.prefixCount ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'bg-slate-800 text-slate-500 border border-white/5'}`}>
                    {p}
                    <button 
                      onClick={() => setSettings({ ...settings, prefixes: settings.prefixes.filter((_, idx) => idx !== i) })}
                      className="ml-2 hover:text-white"
                    >
                      <X size={10} />
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-xl font-bold flex items-center">
              <span className="w-1.5 h-6 bg-amber-500 rounded-full mr-3" />
              Suffix Manager
            </h2>
            <div className="glass-card p-6 rounded-2xl space-y-4">
              <input 
                type="text"
                placeholder="Add new suffix..."
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    const val = (e.target as HTMLInputElement).value.trim();
                    if (val && !settings.suffixes.includes(val)) {
                      setSettings({ ...settings, suffixes: [...settings.suffixes, val] });
                      (e.target as HTMLInputElement).value = '';
                    } else if (settings.suffixes.includes(val)) {
                      showNotification("Suffix already exists.", "warning");
                    }
                  }
                }}
                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm outline-none focus:border-amber-500 transition"
              />
              <div className="flex items-center justify-between text-xs text-slate-500">
                <span>Apply first {settings.suffixCount} suffixes</span>
                <input 
                  type="range" min="0" max={settings.suffixes.length} value={settings.suffixCount}
                  onChange={(e) => setSettings({ ...settings, suffixCount: parseInt(e.target.value) })}
                  className="ml-4 flex-1 h-1.5 bg-white/10 rounded-lg appearance-none cursor-pointer accent-amber-500"
                />
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.suffixes.map((s, i) => (
                  <span key={i} className={`px-3 py-1 rounded-full text-xs flex items-center transition ${i < settings.suffixCount ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' : 'bg-slate-800 text-slate-500 border border-white/5'}`}>
                    {s}
                    <button 
                      onClick={() => setSettings({ ...settings, suffixes: settings.suffixes.filter((_, idx) => idx !== i) })}
                      className="ml-2 hover:text-white"
                    >
                      <X size={10} />
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>
        </section>

        <section className="flex justify-center">
          <button 
            onClick={saveSettings}
            className="px-12 py-4 bg-gradient-to-r from-slate-800 to-slate-900 border border-white/10 hover:border-violet-500/50 rounded-2xl text-white font-bold transition flex items-center group shadow-2xl"
          >
            <SettingsIcon className="mr-3 group-hover:rotate-90 transition-transform duration-500" />
            Save All Settings
          </button>
        </section>
      </main>

      <footer className="border-t border-white/5 bg-slate-950/80 backdrop-blur-xl py-12 px-6">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-12 text-sm">
          <div className="space-y-4">
            <div className="flex items-center opacity-80">
              {LOGO_SVG}
              <span className="font-bold text-xl">Prompt Forge</span>
            </div>
            <p className="text-slate-500 leading-relaxed">
              Professional prompt engineering tool for stock photography and digital artists. Powered by cutting-edge AI models.
            </p>
            <p className="text-slate-400 font-medium">
              © Copyright 2026 PromptForge. All Rights Reserved
            </p>
          </div>
          <div className="grid grid-cols-2 gap-8">
            <div className="space-y-4">
              <h4 className="font-bold text-white uppercase tracking-widest text-xs">Legal</h4>
              <ul className="space-y-2 text-slate-500">
                <li><button onClick={() => setActiveModal('privacy')} className="hover:text-violet-400 transition">Privacy Policy</button></li>
                <li><button onClick={() => setActiveModal('terms')} className="hover:text-violet-400 transition">Terms & Conditions</button></li>
                <li><button onClick={() => setActiveModal('faq')} className="hover:text-violet-400 transition">FAQ</button></li>
              </ul>
            </div>
            <div className="space-y-4">
              <h4 className="font-bold text-white uppercase tracking-widest text-xs">Quick Links</h4>
              <ul className="space-y-2 text-slate-500">
                <li><button onClick={() => setActiveModal('hub')} className="hover:text-violet-400 transition">Community Hub</button></li>
                <li><button onClick={() => setActiveModal('settings')} className="hover:text-violet-400 transition">Settings</button></li>
              </ul>
            </div>
          </div>
          <div className="space-y-4">
            <h4 className="font-bold text-white uppercase tracking-widest text-xs">About Developer</h4>
            <div className="glass-card p-4 rounded-xl flex items-center space-x-4 border border-white/5">
              <div className="w-12 h-12 rounded-full bg-gradient-to-tr from-violet-500 to-fuchsia-500" />
              <div>
                <p className="font-bold">Md. Shawon</p>
                <a href="https://www.behance.net/itsmdshawon" target="_blank" className="text-xs text-violet-400 flex items-center hover:underline">
                  View Portfolio <ExternalLink size={10} className="ml-1" />
                </a>
              </div>
            </div>
          </div>
        </div>
