                      <div className={`flex-shrink-0 flex items-center gap-2 text-xs font-bold ${item.color} opacity-0 group-hover:opacity-100 translate-x-2 group-hover:translate-x-0 transition-all ml-4`}>
                        Join Now <ArrowRight size={14} />
                      </div>
