      q: "Are my images stored on your servers?",
      a: "No. Uploaded images are used only for generating prompts. Images are not permanently stored and are removed when you clear data or leave the session."
    },
    {
      q: "Can I edit or refine generated prompts?",
      a: "Yes. Prompt Forge allows you to refine prompts like a professional prompt engineer. You can improve clarity, structure, and quality even if your original prompt is poorly written or in another language."
    },
    {
      q: "Can I download my prompts?",
      a: "Yes. Generated prompts can be downloaded as a CSV file, making it easy to upload and reuse them for stock or AI workflows."
    },
    {
      q: "Is Prompt Forge suitable for microstock contributors?",
      a: "Yes. Prompt Forge is specifically designed to help microstock contributors generate accurate, stock-ready prompts efficiently."
    }
  ];

  // --- Effects ---
  useEffect(() => {
    const updateModels = async () => {
      const groqModels = await AIService.fetchModels('groq', settings.apiKeys.groq);
      const mistralModels = await AIService.fetchModels('mistral', settings.apiKeys.mistral);

      setModels(prev => {
        const base = prev.filter(m => m.provider === 'gemini');
        const uniqueIds = new Set(base.map(m => m.id));
        const filteredGroq = groqModels.filter(m => !uniqueIds.has(m.id));
        const filteredMistral = mistralModels.filter(m => !uniqueIds.has(m.id));
        return [...base, ...filteredGroq, ...filteredMistral];
      });
    };
    updateModels();
  }, [settings.apiKeys.groq, settings.apiKeys.mistral]);

  // --- Helpers ---
  const showNotification = (message: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3500);
  };

  const saveSettings = () => {
    localStorage.setItem('prompt_forge_settings', JSON.stringify(settings));
    showNotification("Settings saved.");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent<HTMLDivElement>) => {
    let fileList: FileList | null = null;
    if ('dataTransfer' in e) {
      fileList = (e as any).dataTransfer.files;
    } else if ('target' in e && e.target instanceof HTMLInputElement && e.target.files) {
      fileList = e.target.files;
    }

    if (!fileList) return;
    const files = Array.from(fileList);

    const newImages: PromptForgeImage[] = files.map((file: File) => ({
      id: Math.random().toString(36).substring(2, 11),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending',
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const removeImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
  };

  const generatePrompts = async () => {
    if (!images.length) return showNotification("Please upload an image first.", "error");

    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const isGemini = activeModel.provider === 'gemini';
    const apiKey = isGemini ? process.env.API_KEY : (settings.apiKeys as any)[activeModel.provider];

    if (!apiKey) {
      return showNotification(isGemini ? "Gemini key is missing." : `Please add an API key for ${activeModel.provider} in settings.`, "error");
    }

    setIsGenerating(true);
    setGenerationProgress(0);
    setUsageLimitError(null);

    const updatedImages = [...images];
    for (let i = 0; i < updatedImages.length; i++) {
      if (updatedImages[i].status === 'completed') continue;

      try {
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'processing' } : img));

        let promptResult = await AIService.generatePromptFromImage(updatedImages[i], settings, activeModel);

        const prefixes = settings.prefixes.slice(0, settings.prefixCount).join(' ');
        const suffixes = settings.suffixes.slice(0, settings.suffixCount).join(' ');
        const fullPrompt = `${prefixes} ${promptResult} ${suffixes}`.trim().replace(/\s+/g, ' ');

        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'completed', prompt: fullPrompt } : img));
      } catch (error: any) {
        if (error.message.includes('rate limit') || error.message.includes('429')) {
          setUsageLimitError({ modelId: activeModel.id, provider: activeModel.provider });
          setIsGenerating(false);
          return;
        }
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'error', error: error.message } : img));
      }
      setGenerationProgress(((i + 1) / updatedImages.length) * 100);
    }
    setIsGenerating(false);
  };

  const refinePromptAction = async () => {
    if (!refineInput) return;
    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const isGemini = activeModel.provider === 'gemini';
    const apiKey = isGemini ? process.env.API_KEY : (settings.apiKeys as any)[activeModel.provider];

    if (!apiKey) {
      return showNotification(isGemini ? "Gemini key is missing." : `Please add an API key for ${activeModel.provider} in settings.`, "error");
    }

    try {
      setIsGenerating(true);
      const refined = await AIService.refinePrompt(refineInput, settings, activeModel);
      setRefineOutput(refined);
    } catch (error: any) {
      showNotification(`Could not improve prompt: ${error.message}`, "error");
    } finally {
      setIsGenerating(false);
    }
  };

  const exportCSV = () => {
    const header = "No., Image Name, Prompt\n";
    const rows = images.map((img, i) => `${i + 1}, "${img.file.name}", "${img.prompt?.replace(/"/g, '""') || ''}"`).join('\n');
    const blob = new Blob([header + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `my_prompts_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
