      {['privacy', 'terms', 'faq'].includes(activeModal || '') && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="w-full max-w-3xl bg-[#0a0f1d] border border-white/10 rounded-[3rem] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-500">
            <div className="flex items-center justify-between p-10 border-b border-white/5 bg-white/[0.02]">
              <div>
                <h3 className="text-2xl font-black text-white capitalize tracking-tight">{activeModal === 'faq' ? 'FAQ' : activeModal === 'terms' ? 'Terms' : 'Privacy'}</h3>
              </div>
              <button onClick={() => setActiveModal(null)} className="p-3 hover:bg-white/10 rounded-full transition-all text-slate-400 hover:text-white border border-white/5"><X size={24} /></button>
            </div>
            <div className="p-12 max-h-[60vh] overflow-y-auto font-medium text-slate-400 leading-relaxed text-lg scrollbar-hide">
              {activeModal === 'privacy' && (
                <div className="space-y-6">
                  <p>At Prompt Forge, we respect your privacy and are committed to keeping your information safe. This Privacy Policy explains how Prompt Forge works and how user data is handled while using the website and its tools.</p>
                  <p>Prompt Forge does not require users to create an account to use the platform. We do not ask for personal details such as your name, email address, or payment information to access the main features.</p>
                  <p>When using Prompt Forge, users may add API keys, custom instructions, prefixes, or suffixes. These inputs are used only to run the tool as intended and to provide the features requested by the user. Prompt Forge does not sell, share, or use this information for any purpose outside of the tool itself.</p>
                  <p>Images uploaded to Prompt Forge are used only to generate prompts. Images are not permanently stored and are removed when the session ends or when the user clears data.</p>
                  <p>Prompt Forge is designed to function as a tool for creators and contributors. We do not track personal behavior or build user profiles. Any internal data handling is limited to making sure the tool functions correctly.</p>
                  <p>We take reasonable care to keep the platform secure and stable so users can work with confidence.</p>
                </div>
              )}
              {activeModal === 'terms' && (
                <div className="space-y-8">
                  <p>
                    By using this tool, you agree to these simple rules:
                  </p>
                  <ul className="space-y-4 list-disc pl-5 text-sm font-bold text-slate-300">
                    <li>Use your own API keys for most models.</li>
                    <li>Do not create harmful things.</li>
                    <li>You own the prompts you create here.</li>
                  </ul>
                </div>
              )}
              {activeModal === 'faq' && (
                <div className="space-y-4">
                  {faqData.map((item, index) => (
                    <div 
                      key={index} 
                      className={`glass-card rounded-2xl overflow-hidden border border-white/5 transition-all duration-300 ${expandedFaq === index ? 'border-violet-500/30 bg-white/[0.05]' : 'hover:border-white/10'}`}
                    >
                      <button 
                        onClick={() => setExpandedFaq(expandedFaq === index ? null : index)}
                        className="w-full p-5 lg:p-6 flex items-center justify-between gap-4 text-left"
                      >
                        <span className="text-base lg:text-lg font-bold text-white tracking-tight">{item.q}</span>
                        <div className={`p-1.5 rounded-full bg-white/5 transition-transform duration-300 ${expandedFaq === index ? 'rotate-180 bg-violet-500/20 text-violet-400' : 'text-slate-500'}`}>
                          {expandedFaq === index ? <Minus size={18} /> : <Plus size={18} />}
                        </div>
                      </button>
                      <div 
                        className={`transition-all duration-300 ease-in-out overflow-hidden ${expandedFaq === index ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}
                      >
                        <div className="p-6 pt-0 text-slate-400 text-base leading-relaxed border-t border-white/5 mt-0.5">
                          {item.a}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, 
  Minus,
  Trash2, 
  Download, 
  Settings as SettingsIcon, 
  RotateCcw, 
  MessageSquare, 
  Share2, 
  ChevronDown, 
  X, 
  Copy, 
  Check, 
  AlertCircle,
  ExternalLink,
  ChevronRight,
  Sparkles,
  Layers,
  LayoutGrid,
  Headphones,
  Youtube,
  Users,
  User,
  ArrowRight,
  Mail,
  Phone,
  ImagePlus,
  FileText,
  Loader2,
  FileCheck,
  Trophy
} from 'lucide-react';
import { 
  PromptForgeImage, 
  Settings, 
  Model, 
  Provider
} from './types';
import { 
  INITIAL_MODELS, 
  DEFAULT_SETTINGS, 
  LOGO_SVG 
} from './constants';
import { AIService } from './services/aiService';

export default function App() {
  // --- State ---
  const [images, setImages] = useState<PromptForgeImage[]>([]);
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('prompt_forge_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });
  const [models, setModels] = useState<Model[]>(INITIAL_MODELS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [currentProcessingIndex, setCurrentProcessingIndex] = useState(0);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [activeModal, setActiveModal] = useState<'hub' | 'settings' | 'privacy' | 'terms' | 'faq' | 'contact' | null>(null);
  const [refineInput, setRefineInput] = useState('');
  const [refineOutput, setRefineOutput] = useState('');
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'error' | 'warning' } | null>(null);
  const [usageLimitError, setUsageLimitError] = useState<{ modelId: string; provider: Provider } | null>(null);
  const [expandedFaq, setExpandedFaq] = useState<number | null>(null);

  // --- Refs ---
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- FAQ Data ---
  const faqData = [
    {
      q: "What is Prompt Forge?",
      a: "Prompt Forge is an AI-powered tool that helps you turn images into detailed and accurate prompts. It is built for creators and microstock contributors who want high-quality prompts for generating similar images using AI tools."
    },
    {
      q: "How does the image to prompt feature work?",
      a: "You upload one or more images, and Prompt Forge analyzes each image to understand details like subject, style, lighting, and composition. Based on this analysis, it generates a complete prompt that can be reused in different AI image generation models."
    },
    {
      q: "Do I need my own API keys to use Prompt Forge?",
      a: "Yes, Prompt Forge uses your own API keys for supported AI models. This gives you full control over usage, limits, and model selection."
    },
    {
      q: "Which AI models are supported?",
      a: "Prompt Forge supports multiple AI providers including Google Gemini models, Groq models, and Mistral AI models. You can switch models at any time if a usage limit is reached."
    },
    {
      q: "Are my images stored on your servers?",
      a: "No. Uploaded images are used only for generating prompts. Images are not permanently stored and are removed when you clear data or leave the session."
    },
    {
      q: "Can I edit or refine generated prompts?",
      a: "Yes. Prompt Forge allows you to refine prompts like a professional prompt engineer. You can improve clarity, structure, and quality even if your original prompt is poorly written or in another language."
    },
    {
      q: "Can I download my prompts?",
      a: "Yes. Generated prompts can be downloaded as a CSV file, making it easy to upload and reuse them for stock or AI workflows."
    },
    {
      q: "Is Prompt Forge suitable for microstock contributors?",
      a: "Yes. Prompt Forge is specifically designed to help microstock contributors generate accurate, stock-ready prompts efficiently."
    }
  ];

  // --- Effects ---
  useEffect(() => {
    const updateModels = async () => {
      const groqModels = await AIService.fetchModels('groq', settings.apiKeys.groq);
      const mistralModels = await AIService.fetchModels('mistral', settings.apiKeys.mistral);

      setModels(prev => {
        const base = prev.filter(m => m.provider === 'gemini');
        const uniqueIds = new Set(base.map(m => m.id));
        const filteredGroq = groqModels.filter(m => !uniqueIds.has(m.id));
        const filteredMistral = mistralModels.filter(m => !uniqueIds.has(m.id));
        return [...base, ...filteredGroq, ...filteredMistral];
      });
    };
    updateModels();
  }, [settings.apiKeys.groq, settings.apiKeys.mistral]);

  // --- Helpers ---
  const showNotification = (message: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3500);
  };

  const saveSettings = () => {
    localStorage.setItem('prompt_forge_settings', JSON.stringify(settings));
    showNotification("Settings saved.");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent<HTMLDivElement>) => {
    let fileList: FileList | null = null;
    if ('dataTransfer' in e) {
      fileList = (e as any).dataTransfer.files;
    } else if ('target' in e && e.target instanceof HTMLInputElement && e.target.files) {
      fileList = e.target.files;
    }

    if (!fileList) return;
    const files = Array.from(fileList);

    // Performance optimization: No previewUrl creation for batch uploads
    const newImages: PromptForgeImage[] = files.map((file: File) => ({
      id: Math.random().toString(36).substring(2, 11),
      file,
      previewUrl: '', // Previews disabled for performance
      status: 'pending',
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const removeImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
  };

  const clearImages = () => {
    setImages([]);
    setGenerationProgress(0);
    setCurrentProcessingIndex(0);
  };

  const generatePrompts = async () => {
    if (!images.length) return showNotification("Please upload an image first.", "error");

    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const isGemini = activeModel.provider === 'gemini';
    const apiKey = isGemini ? process.env.API_KEY : (settings.apiKeys as any)[activeModel.provider];

    if (!apiKey) {
      return showNotification(isGemini ? "Gemini key is missing." : `Please add an API key for ${activeModel.provider} in settings.`, "error");
    }

    setIsGenerating(true);
    setGenerationProgress(0);
    setCurrentProcessingIndex(0);
    setUsageLimitError(null);

    const updatedImages = [...images];
    for (let i = 0; i < updatedImages.length; i++) {
      if (updatedImages[i].status === 'completed') continue;

      setCurrentProcessingIndex(i + 1);
      try {
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'processing' } : img));

        let promptResult = await AIService.generatePromptFromImage(updatedImages[i], settings, activeModel);

        const prefixes = settings.prefixes.slice(0, settings.prefixCount).join(' ');
        const suffixes = settings.suffixes.slice(0, settings.suffixCount).join(' ');
        const fullPrompt = `${prefixes} ${promptResult} ${suffixes}`.trim().replace(/\s+/g, ' ');

        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'completed', prompt: fullPrompt } : img));
      } catch (error: any) {
        if (error.message.includes('rate limit') || error.message.includes('429')) {
          setUsageLimitError({ modelId: activeModel.id, provider: activeModel.provider });
          setIsGenerating(false);
          return;
        }
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'error', error: error.message } : img));
      }
      setGenerationProgress(((i + 1) / updatedImages.length) * 100);
    }
    setIsGenerating(false);
  };

  const refinePromptAction = async () => {
    if (!refineInput) return;
    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const isGemini = activeModel.provider === 'gemini';
    const apiKey = isGemini ? process.env.API_KEY : (settings.apiKeys as any)[activeModel.provider];

    if (!apiKey) {
      return showNotification(isGemini ? "Gemini key is missing." : `Please add an API key for ${activeModel.provider} in settings.`, "error");
    }

    try {
      setIsGenerating(true);
      const refined = await AIService.refinePrompt(refineInput, settings, activeModel);
      setRefineOutput(refined);
    } catch (error: any) {
      showNotification(`Could not improve prompt: ${error.message}`, "error");
    } finally {
      setIsGenerating(false);
    }
  };

  const exportCSV = () => {
    const header = "No., Image Name, Prompt\n";
    const rows = images.map((img, i) => `${i + 1}, "${img.file.name}", "${img.prompt?.replace(/"/g, '""') || ''}"`).join('\n');
    const blob = new Blob([header + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `my_prompts_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    showNotification("Copied!");
  };

  const hasResults = images.some(img => img.status === 'completed');
  const allPending = images.length > 0 && images.every(img => img.status === 'pending');
  const completedCount = images.filter(i => i.status === 'completed').length;
  const errorCount = images.filter(i => i.status === 'error').length;

  return (
    <div className={`min-h-screen transition-colors duration-300 ${settings.theme === 'light' ? 'bg-slate-50 text-slate-900' : 'bg-[#020617] text-slate-200'}`}>
      <div className="fixed inset-0 pointer-events-none gradient-bg -z-10" />

      {/* Header */}
      <header className="sticky top-0 z-40 backdrop-blur-xl border-b border-white/5 px-6 py-4">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center group cursor-default">
            <div className="transform group-hover:scale-110 transition-transform duration-500">
              {LOGO_SVG}
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-extrabold tracking-tight text-white">
                Prompt <span className="bg-clip-text text-transparent bg-gradient-to-r from-violet-400 via-fuchsia-400 to-indigo-400">Forge</span>
              </h1>
              <p className="text-[10px] uppercase tracking-[0.15em] text-slate-500 font-bold">Make Better Prompts For Real Result</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <button 
              onClick={() => setActiveModal(activeModal === 'hub' ? null : 'hub')}
              className={`hidden sm:flex px-5 py-2.5 rounded-full transition-all text-sm font-bold border ${
                activeModal === 'hub' 
                ? 'bg-violet-500/10 border-violet-500/30 text-violet-400 shadow-[0_0_20px_rgba(139,92,246,0.15)]' 
                : 'glass-card hover:bg-white/10 text-slate-200 border-white/10'
              }`}
            >
              <Share2 size={16} className={`mr-2 transition-transform duration-300 ${activeModal === 'hub' ? 'scale-110' : ''}`} />
              Community
            </button>
            <button 
              onClick={() => setActiveModal('settings')}
              className={`px-5 py-2.5 rounded-full transition-all border group flex items-center text-sm font-bold ${
                activeModal === 'settings'
                ? 'bg-violet-500/10 border-violet-500/30 text-violet-400'
                : 'glass-card hover:bg-white/10 text-slate-200 border-white/10'
              }`}
            >
              <SettingsIcon size={20} className="mr-2 group-hover:rotate-45 transition-transform" />
              Settings
            </button>
            <button 
              onClick={() => setActiveModal(activeModal === 'contact' ? null : 'contact')}
              className={`hidden sm:flex px-5 py-2.5 rounded-full transition-all text-sm font-bold border ${
                activeModal === 'contact' 
                ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.15)]' 
                : 'glass-card hover:bg-white/10 text-slate-200 border-white/10'
              }`}
            >
              Contact
            </button>
          </div>
        </div>
      </header>

      {/* Usage Limit Banner */}
      {usageLimitError && (
        <div className="bg-amber-500/10 border-b border-amber-500/20 px-6 py-3 text-center animate-in slide-in-from-top duration-300">
          <p className="text-amber-300 text-sm font-semibold flex items-center justify-center">
            <AlertCircle size={16} className="mr-2" />
            Limit reached for {usageLimitError.modelId}.
            <button 
              onClick={() => setActiveModal('settings')}
              className="ml-4 px-3 py-1 bg-amber-500/20 hover:bg-amber-500/30 rounded-full text-xs transition-all font-bold"
            >
              Change AI Model
            </button>
          </p>
        </div>
      )}

      {/* Notifications */}
      {notification && (
        <div className={`fixed bottom-10 left-1/2 -translate-x-1/2 z-50 px-6 py-3.5 rounded-2xl shadow-2xl flex items-center border backdrop-blur-md animate-in slide-in-from-bottom-8 fade-in duration-500 ${
          notification.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' :
          notification.type === 'error' ? 'bg-rose-500/10 border-rose-500/20 text-rose-400' :
          'bg-amber-500/10 border-amber-500/20 text-amber-400'
        }`}>
          {notification.type === 'success' ? <Check size={18} className="mr-3" /> : <AlertCircle size={18} className="mr-3" />}
          <span className="font-semibold text-sm">{notification.message}</span>
        </div>
      )}

      <main className="max-w-6xl mx-auto px-6 py-12 lg:py-20 space-y-24">

        {/* Section 1: Hero & Upload */}
        <section className="space-y-10">
          <div className="text-center space-y-4 max-w-2xl mx-auto">
            <h2 className="text-4xl lg:text-5xl font-black tracking-tight leading-[1.1] text-white text-balance">
              Turn your images into <span className="text-transparent bg-clip-text bg-gradient-to-r from-violet-400 to-fuchsia-400">amazing prompts</span>
            </h2>
            <p className="text-slate-400 text-lg lg:text-xl font-medium leading-relaxed text-balance">
              Upload your photos and our AI will create great prompts for you.
            </p>
          </div>

          <div 
            className="relative group p-16 lg:p-24 border-2 border-dashed border-white/10 rounded-[2.5rem] text-center glass-card hover:border-violet-500/40 transition-all duration-500 cursor-pointer overflow-hidden premium-shadow"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => { e.preventDefault(); handleFileUpload(e); }}
            onClick={() => fileInputRef.current?.click()}
          >
            <div className="absolute inset-0 bg-gradient-to-b from-transparent to-violet-500/5 opacity-0 group-hover:opacity-100 transition-opacity" />
            <input 
              ref={fileInputRef}
              type="file" 
              multiple 
              className="absolute inset-0 opacity-0 cursor-pointer" 
              onChange={handleFileUpload} 
              accept="image/png, image/jpeg, image/jpg"
            />
            <div className="relative z-10 space-y-6">
              <div className="w-24 h-24 bg-gradient-to-tr from-violet-600/20 to-fuchsia-600/20 border border-white/10 rounded-3xl flex items-center justify-center mx-auto group-hover:scale-110 group-hover:rotate-3 transition-all duration-500">
                <Plus size={48} className="text-violet-400" />
              </div>
              <div className="space-y-2">
                <p className="text-2xl font-bold text-white tracking-tight">Drop your images here</p>
                <p className="text-slate-500 font-medium text-balance px-4">Drag files here or click Add Images to begin (Jpg, Jpeg & Png)</p>
              </div>
            </div>
          </div>

          {/* Upload Confirmation Indicator */}
          {allPending && !isGenerating && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 flex justify-center">
              <div className="glass-card px-8 py-6 rounded-[2rem] border-emerald-500/20 bg-emerald-500/5 flex items-center gap-4 premium-shadow">
                <div className="w-12 h-12 bg-emerald-500/10 rounded-2xl flex items-center justify-center text-emerald-400">
                  <FileCheck size={24} />
                </div>
                <div>
                  <p className="text-lg font-black text-white tracking-tight">{images.length} images added successfully</p>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Ready to forge prompts</p>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); clearImages(); }}
                  className="ml-4 p-2.5 hover:bg-rose-500/20 text-slate-500 hover:text-rose-400 rounded-xl transition-all"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          )}

          {/* Detailed Progress Section */}
          {isGenerating && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-500 space-y-8 max-w-2xl mx-auto py-10 px-8 glass-card rounded-[2.5rem] border-violet-500/20 bg-violet-500/5">
              <div className="text-center space-y-3">
                <div className="w-16 h-16 bg-violet-500/10 rounded-full flex items-center justify-center mx-auto mb-4 border border-violet-500/20 relative">
                  <Loader2 size={32} className="text-violet-400 animate-spin" />
                  <div className="absolute -top-1 -right-1 w-4 h-4 bg-fuchsia-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(217,70,239,0.5)]" />
                </div>
                <h3 className="text-2xl font-black text-white tracking-tight">Processing {currentProcessingIndex} of {images.length} images</h3>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-[0.2em] animate-pulse">Forging high-quality prompts...</p>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between text-[10px] font-black text-slate-500 uppercase tracking-widest">
                  <span>Progress Status</span>
                  <span>{Math.round(generationProgress)}% Complete</span>
                </div>
                <div className="w-full h-4 bg-slate-950/50 rounded-full overflow-hidden p-1 border border-white/5">
                  <div 
                    className="h-full bg-gradient-to-r from-violet-500 via-fuchsia-500 to-indigo-500 rounded-full transition-all duration-700 shadow-[0_0_20px_rgba(139,92,246,0.3)]" 
                    style={{ width: `${generationProgress}%` }}
                  />
                </div>
              </div>

              <div className="flex items-center justify-center gap-6 pt-4">
                <div className="flex flex-col items-center">
                  <span className="text-xl font-black text-white">{currentProcessingIndex}</span>
                  <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Done</span>
                </div>
                <div className="w-px h-8 bg-white/10" />
                <div className="flex flex-col items-center">
                  <span className="text-xl font-black text-slate-500">{images.length - currentProcessingIndex}</span>
                  <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Remaining</span>
                </div>
              </div>
            </div>
          )}

          {/* Performance Optimized Completion Section (No prompt grid) */}
          {hasResults && !isGenerating && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000 flex flex-col items-center gap-10">
              <div className="glass-card w-full max-w-2xl p-12 rounded-[3rem] border-fuchsia-500/20 bg-fuchsia-500/5 text-center space-y-6 premium-shadow relative overflow-hidden">
                {/* Background Accent */}
                <div className="absolute -top-10 -right-10 p-6 opacity-5 rotate-12 pointer-events-none">
                  <Trophy size={180} />
                </div>

                <div className="w-20 h-20 bg-fuchsia-500/10 rounded-[2rem] flex items-center justify-center mx-auto mb-6 border border-fuchsia-500/20">
                  <Check size={40} className="text-fuchsia-400" />
                </div>

                <div className="space-y-2">
                  <h3 className="text-3xl font-black text-white tracking-tight">Processing completed successfully</h3>
                  <p className="text-slate-400 font-medium text-lg">Your batch is ready! We've generated {completedCount} high-quality prompts for you.</p>
                </div>

                <div className="flex items-center justify-center gap-4 py-4">
                  <div className="px-6 py-3 bg-white/5 rounded-2xl border border-white/10 flex items-center gap-3">
                    <Sparkles size={16} className="text-fuchsia-400" />
                    <span className="text-sm font-black text-white">{completedCount} Prompts Ready</span>
