                <div className="flex flex-col items-center">
                  <span className="text-xl font-black text-slate-500">{images.length - currentProcessingIndex}</span>
                  <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Remaining</span>
                </div>
              </div>
            </div>
          )}

          {/* Performance Optimized Completion Section (No prompt grid) */}
          {hasResults && !isGenerating && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000 flex flex-col items-center gap-10">
              <div className="glass-card w-full max-w-2xl p-12 rounded-[3rem] border-fuchsia-500/20 bg-fuchsia-500/5 text-center space-y-6 premium-shadow relative overflow-hidden">
                {/* Background Accent */}
                <div className="absolute -top-10 -right-10 p-6 opacity-5 rotate-12 pointer-events-none">
                  <Trophy size={180} />
