        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`,
        'Accept': 'application/json'
      },
      body: JSON.stringify({
        model: effectiveModelId,
        messages: [
          ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
          { role: 'user', content: contentParts }
        ],
        temperature: 0.7,
        max_tokens: max_tokens, // Use provided or default
        stream: false
      }),
      signal: controller.signal
    });

    if (!response.ok) {
      const errData = await response.json().catch(() => ({}));
      const statusMsg = errData.error?.message || `HTTP ${response.status}`;
      throw new Error(`[${provider.toUpperCase()}] ${statusMsg}`);
    }

    const data = await response.json();
    if (!data.choices || data.choices.length === 0 || !data.choices[0].message) {
      throw new Error(`[${provider.toUpperCase()}] No choices returned from API.`);
    }

    return {
      text: data.choices[0].message.content,
      usage: data.usage // Include usage data
    };
  } catch (error: any) {
    if (error.name === 'AbortError') {
      throw new Error('[GROQ] Request aborted.');
    } else {
      console.error('[GROQ] API Error:', error);
      throw error; // Re-throw to be handled by the caller, e.g., retry logic
    }
  }
}
