import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

// Helper to convert File to base64
const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = reader.result as string;
      resolve(base64String.split(',')[1]);
    };
    reader.onerror = error => reject(error);
  });
};

// Global state for key rotation indices to persist during session
const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  /**
   * Universal key manager. Handles rotation and error detection.
   * Throws "EXHAUSTED" if all keys in the pool fail.
   */
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      throw new Error(`MISSING_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        // Attempt with extremely aggressive retries (15 times) for critical models like Llama 4 Scout Fast
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; // Save success index
        return result;
      } catch (error: any) {
        console.warn(`Key ${currentIndex} for ${provider} failed after 15 retries. Error: ${error.message}. Rotating...`);
        attempts++;
      }
    }

    throw new Error(`EXHAUSTED_${provider.toUpperCase()}`);
  }

  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 15): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = e.message?.toLowerCase() || "";
      const isAbort = e.name === 'AbortError' || err.includes('aborted');

      // Broadened retry conditions to cover all transient errors
      const shouldRetry = 
        isAbort ||
        err.includes("429") || 
        err.includes("500") || 
        err.includes("502") || 
        err.includes("503") || 
        err.includes("504") || 
        err.includes("timeout") || 
        err.includes("gateway") ||
        err.includes("limit") ||
        err.includes("rate") ||
        err.includes("connection") ||
        err.includes("fetch") ||
        err.includes("network") ||
        err.includes("refused") ||
        err.includes("overloaded") ||
        err.includes("unavailable");

      if (retries > 0 && shouldRetry) {
        // High intensity jittered backoff for rapid recovery
        const delay = 1000 + (Math.random() * 2000);
        await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    apiKey: string,
    modelId: string, 
    prompt: string, 
    image?: PromptForgeImage,
    systemInstruction?: string
  ) {
    const ai = new GoogleGenAI({ apiKey });

    const parts: any[] = [{ text: prompt }];
    if (image) {
      const base64Data = await fileToBase64(image.file);
      parts.unshift({
        inlineData: {
          mimeType: image.file.type,
          data: base64Data
        }
      });
    }

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });

    return response.text;
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    image?: PromptForgeImage,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';

    // Internal mapping to ensure valid model IDs for Groq/Mistral placeholders
    let actualModelId = modelId;
    if (provider === 'groq') {
      if (modelId === 'llama-4-scout-fast') actualModelId = 'llama-3.2-11b-vision-preview';
      else if (modelId === 'llama-4-maverick-hq') actualModelId = 'llama-3.2-90b-vision-preview';
    } else if (provider === 'mistral') {
      if (modelId === 'pixtral-12b-vision') actualModelId = 'pixtral-12b-2409';
      else if (modelId === 'open-mistral-nemo') actualModelId = 'open-mistral-nemo-2407';
    }

    // Construct payload ensuring text part always exists and image follows if present
    const contentParts: any[] = [{ type: 'text', text: prompt }];

    if (image) {
      const base64Data = await fileToBase64(image.file);
      contentParts.push({
        type: 'image_url',
        image_url: { 
          url: `data:${image.file.type};base64,${base64Data}` 
        }
      });
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 120000); // 120s timeout for stability

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
          'Accept': 'application/json'
        },
        body: JSON.stringify({
          model: actualModelId,
          messages: [
            ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
            { role: 'user', content: contentParts }
          ],
          temperature: 0.7,
          max_tokens: 1024,
          stream: false
        }),
        signal: controller.signal
      });

      if (!response.ok) {
        const errData = await response.json().catch(() => ({}));
        throw new Error(errData.error?.message || `Provider API Error ${response.status}`);
      }

      const data = await response.json();
      if (!data.choices || data.choices.length === 0 || !data.choices[0].message) {
        throw new Error("Provider returned an invalid or empty choice set.");
      }
      return data.choices[0].message.content;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  public static async generatePromptFromImage(
    image: PromptForgeImage,
    settings: Settings,
    model: Model
  ) {
    if (!model.hasVision) {
      throw new Error("This model does not support images. Please select a vision-capable model.");
    }

    const systemPrompt = `You are a professional stock photography prompt engineer. 
    Analyze the provided image and extract a rich, detailed, stock-ready prompt.
    Include composition, lighting, color palette, camera lens/angle, subject details, textures, background.
    Output: ONE CLEAR PARAGRAPH. No bullet lists. No symbols. Professional language. English only.
    ${settings.customInstruction ? `\nGlobal Instruction: ${settings.customInstruction}` : ''}`;

    const userPrompt = "Describe this image in detail for re-creation in an AI image generator.";

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, userPrompt, image, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, userPrompt, image, systemPrompt);
      }
    });
  }

  public static async refinePrompt(
    input: string,
    settings: Settings,
    model: Model
  ) {
    const systemPrompt = `Refine the user's prompt into a powerful, professional English prompt paragraph.
    Clean grammar, remove extra characters, translate to English if needed. 
    Output should be one powerful paragraph. No bullets.
    ${settings.customInstruction ? `\nGlobal Instruction: ${settings.customInstruction}` : ''}`;

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, input, undefined, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, input, undefined, systemPrompt);
      }
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    return [];
  }
}

