  /**
   * Universal key manager. Handles rotation and error detection.
   * Throws "EXHAUSTED" if all keys in the pool fail.
   */
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      // Allow Gemini to fall back to process.env.API_KEY if configured in window/env context
      if (provider === 'gemini' && typeof process !== 'undefined' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY);
      }
      throw new Error(`MISSING_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        // Use extremely aggressive retries before deciding a key is "bad"
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; // Pin successful index
        return result;
      } catch (error: any) {
        const msg = error.message?.toLowerCase() || "";
        // If it's an auth error (401), rotate immediately. 
        // Otherwise, it was a transient error that failed after many retries.
        if (msg.includes("401") || msg.includes("auth") || msg.includes("invalid key") || msg.includes("unauthorized")) {
           console.warn(`Key ${currentIndex} for ${provider} is invalid/unauthorized. Rotating...`);
        } else {
           console.error(`Key ${currentIndex} for ${provider} failed repeatedly. Rotating key... Original error: ${error.message}`);
        }
        attempts++;
      }
    }

    throw new Error(`EXHAUSTED_${provider.toUpperCase()}`);
  }

  /**
   * High-intensity retry wrapper to bridge intermittent network/gateway drops.
   */
  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 20): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = e.message?.toLowerCase() || "";

      // Do NOT retry on 401 Unauthorized - the key is simply wrong
      if (err.includes("401") || err.includes("unauthorized") || err.includes("invalid api key")) {
        throw e;
      }

      // Retry on basically everything else: 429, 5xx, timeouts, network drops, empty responses
      if (retries > 0) {
        // Jittered backoff to avoid synchronized slamming of the API
        const delay = 800 + (Math.random() * 1200);
        console.log(`Transient error: "${e.message}". Retrying in ${Math.round(delay)}ms... (${retries} retries left)`);
        await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

