    setImages(prev => [...prev, ...newImages]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => {
      const img = prev.find(i => i.id === id);
      if (img) URL.revokeObjectURL(img.previewUrl);
      return prev.filter(i => i.id !== id);
    });
  };

  const processImage = async (id: string) => {
    const img = images.find(i => i.id === id);
    if (!img) return;

    setImages(prev => prev.map(i => i.id === id ? { ...i, status: 'processing', error: undefined } : i));

    try {
      const prompt = await AIService.generatePromptFromImage(img, settings, activeModel);
      setImages(prev => prev.map(i => i.id === id ? { ...i, status: 'completed', prompt } : i));
    } catch (err: any) {
      setImages(prev => prev.map(i => i.id === id ? { ...i, status: 'error', error: err.message } : i));
    }
  };

