import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

/**
 * High-Speed Optimized Image Processor
 * Significantly reduces payload size to maximize upload and inference speed.
 * Lowering dimensions is the single most effective way to speed up Vision APIs.
 */
const prepareImage = (file: File, maxDim: number, quality: number = 0.6): Promise<{data: string, mime: string}> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'low'; // Faster scaling
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        // Use JPEG with optimized quality for fastest possible POST transfer
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      if (provider === 'gemini' && typeof process !== 'undefined' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY);
      }
      throw new Error(`NO_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    let lastError = "";

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        lastError = error.message;
        attempts++;
      }
    }

    throw new Error(`PROVIDER_FAILURE_${provider.toUpperCase()}: ${lastError}`);
  }

  /**
   * Ultra-Fast Retry Strategy
   * First 3 attempts are instant to recover from micro-glitches with zero perceived delay.
   */
  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 10): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = e.message?.toLowerCase() || "";
      if (err.includes("401") || err.includes("unauthorized") || err.includes("invalid api key")) throw e;

      if (retries > 0) {
        const attemptNumber = 10 - retries;
        // Zero delay for the first 3 retries (instant recovery)
        const delay = attemptNumber < 3 ? 0 : 200 + (Math.random() * 200);
        if (delay > 0) await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    apiKey: string,
    modelId: string, 
    prompt: string, 
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const ai = new GoogleGenAI({ apiKey });
    const parts: any[] = [{ text: prompt }];
    if (base64Data && mimeType) {
      parts.unshift({ inlineData: { mimeType, data: base64Data } });
    }
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { systemInstruction, temperature: 0.7 }
    });
    return response.text;
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';
    let actualModelId = modelId;
    let temperature = 0.7;
    let maxTokens = 1024;
    let timeout = 20000; // Aggressive timeout for faster failover

    if (provider === 'groq') {
      if (modelId === 'llama-4-scout-fast') {
        actualModelId = 'llama-3.2-11b-vision-preview';
        temperature = 0.0; // Greedy decoding = fastest inference
        maxTokens = 250;
        timeout = 10000;
      } else if (modelId === 'llama-4-maverick-hq') {
        actualModelId = 'llama-3.2-90b-vision-preview';
        temperature = 0.0;
        maxTokens = 400;
        timeout = 18000;
      }
    } else if (provider === 'mistral') {
      if (modelId === 'pixtral-12b-vision') {
        actualModelId = 'pixtral-12b-2409';
        maxTokens = 400; // Standardize output length for speed
        timeout = 15000;
      }
    }

    const messages: any[] = [];
    if (systemInstruction) {
      messages.push({ role: 'system', content: systemInstruction });
    }

    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout); 

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey.trim()}`
        },
        body: JSON.stringify({
          model: actualModelId,
          messages,
          temperature,
          max_tokens: maxTokens,
          stream: false
        }),
        signal: controller.signal
      });

      if (!response.ok) {
        const text = await response.text();
        throw new Error(text || `HTTP ${response.status}`);
      }

      const data = await response.json();
      const content = data.choices?.[0]?.message?.content;
      if (!content) throw new Error("EMPTY_RESPONSE");
      return content;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  public static async generatePromptFromImage(image: PromptForgeImage, settings: Settings, model: Model) {
    if (!model.hasVision) throw new Error("VISION_UNSUPPORTED");

    // DYNAMIC PAYLOAD OPTIMIZATION
    // Smaller images process significantly faster on Groq/Mistral infrastructure
    let maxDim = 800;
    let quality = 0.7;

    if (model.id === 'llama-4-scout-fast') {
      maxDim = 512; // Hyper-fast 11B processing
      quality = 0.6;
    } else if (model.id === 'llama-4-maverick-hq') {
      maxDim = 800; // Stable high quality for 90B
    } else if (model.provider === 'mistral') {
      maxDim = 640; // Pixtral sweet spot
    }

    const { data, mime } = await prepareImage(image.file, maxDim, quality);

    const systemPrompt = `You are a professional stock photography prompt engineer. Output: ONE CLEAR PARAGRAPH. No bullets. No symbols. English only. ${settings.customInstruction}`;
    const userPrompt = "Generate a professional image prompt for this visual content.";

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, userPrompt, data, mime, systemPrompt);
      }
      return await this.providerGenerate(model.provider, key, model.id, userPrompt, data, mime, systemPrompt);
    });
  }

  public static async refinePrompt(input: string, settings: Settings, model: Model) {
    const systemPrompt = `Refine the user's prompt into a professional English prompt paragraph. No bullets. ${settings.customInstruction}`;
    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, input, undefined, undefined, systemPrompt);
      }
      return await this.providerGenerate(model.provider, key, model.id, input, undefined, undefined, systemPrompt);
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    return [];
  }
}

