        if (error.message.includes('EXHAUSTED')) {
          setUsageLimitError({ modelId: activeModel.id, provider: activeModel.provider });
          setIsGenerating(false);
          setIsPaused(true);
          showNotification(`All keys exhausted for ${activeModel.provider}. Processing paused.`, "error");
          return;
        }
        const targetId = currentImg.id;
        setImages(prev => prev.map(img => img.id === targetId ? { ...img, status: 'error', error: error.message } : img));
        setCurrentProcessingIndex(i + 1);
      }

      setGenerationProgress(((i + 1) / imagesRef.current.length) * 100);
