        // Accessing img.prompt which is populated during generatePrompts
        const promptContent = img.prompt || ""; 
        // Escape quotes for CSV
        const escapedPrompt = promptContent.replace(/"/g, '""');
        return `${serialNo}, "${escapedPrompt}"`;
    }).join('\n');

    const blob = new Blob([header + rows], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `prompt_forge_export_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 150);
  };

