          {hasImages && (
            <section className="space-y-6 pt-6">
               <div className="flex items-center justify-between px-2">
                 <h3 className="text-xl font-black text-white tracking-tight uppercase tracking-[0.1em]">Verification Panel</h3>
                 <p className="text-xs font-bold text-slate-500">Live preview of generated data</p>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {images.map((img, idx) => (
                   <div key={img.id} className="glass-card p-6 rounded-3xl border border-white/5 flex gap-4 items-start">
