/**
 * High-Speed Optimized Image Processor
 */
const prepareImage = (file: File, maxDim: number, quality: number = 0.6): Promise<{data: string, mime: string}> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'low';
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

const keyIndices: Record<string, number> = {
  groq: 0,
  mistral: 0
};

export class AIService {
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    // For Gemini, always use the environment variable as per guidelines
    if (provider === 'gemini') {
      if (!process.env.API_KEY) {
        throw new Error("GEMINI_API_KEY_MISSING");
      }
      return await this.retryTask(task, process.env.API_KEY);
    }

    if (!keys || keys.length === 0) {
      throw new Error(`NO_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    let lastError = "";

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        lastError = error.message;
        attempts++;
      }
    }

    throw new Error(`PROVIDER_FAILURE_${provider.toUpperCase()}: ${lastError}`);
  }

  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 5): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = e.message?.toLowerCase() || "";
      if (err.includes("401") || err.includes("unauthorized") || err.includes("invalid api key")) throw e;

      if (retries > 0) {
        const attemptNumber = 5 - retries;
        const delay = attemptNumber < 2 ? 0 : 500 + (Math.random() * 500);
        if (delay > 0) await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    modelId: string, 
    prompt: string, 
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    // Initializing GoogleGenAI with the environment variable as per hard requirement
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const parts: any[] = [];

    if (base64Data && mimeType) {
      parts.push({ inlineData: { mimeType, data: base64Data } });
    }
    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { 
        systemInstruction, 
        temperature: 0.1 
      }
    });

    // Always use .text property as per guidelines
    const text = response.text;
    if (!text || typeof text !== 'string' || text.trim().length < 5) {
      throw new Error("AI returned empty or invalid text.");
    }
    return text.trim();
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';
    let actualModelId = modelId;
    let temperature = 0.1;
    let maxTokens = 800;

    if (provider === 'groq') {
      if (modelId === 'llama-4-scout-fast') {
        actualModelId = 'llama-3.2-11b-vision-preview';
        temperature = 0.0;
      } else if (modelId === 'llama-4-maverick-hq') {
        actualModelId = 'llama-3.2-90b-vision-preview';
        temperature = 0.0;
      }
    } else if (provider === 'mistral') {
      if (modelId === 'pixtral-12b-vision') {
        actualModelId = 'pixtral-12b-2409';
      }
    }

    const messages: any[] = [];
    if (systemInstruction) {
      messages.push({ role: 'system', content: systemInstruction });
    }

    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey.trim()}`
      },
      body: JSON.stringify({
        model: actualModelId,
        messages,
        temperature,
        max_tokens: maxTokens,
        stream: false
      })
    });

    if (!response.ok) {
      const text = await response.text();
      throw new Error(text || `HTTP ${response.status}`);
    }

    const data = await response.json();
    const content = data.choices?.[0]?.message?.content;
    if (!content || content.trim().length < 5) throw new Error("AI provider returned empty response.");
    return content.trim();
  }

  public static async generatePromptFromImage(image: PromptForgeImage, settings: Settings, model: Model) {
    if (!model.hasVision) throw new Error("VISION_UNSUPPORTED");

    let maxDim = 800;
    let quality = 0.7;

    if (model.id === 'llama-4-scout-fast') {
      maxDim = 512;
      quality = 0.6;
    } else if (model.id === 'llama-4-maverick-hq') {
      maxDim = 800;
    } else if (model.provider === 'mistral') {
      maxDim = 640;
    }

    const { data, mime } = await prepareImage(image.file, maxDim, quality);

    const systemPrompt = `You are a professional image prompt engineer.
Analyze the image and create a complete prompt for AI image generators.
INSTRUCTIONS:
1. Use very simple English. Think of a 10-year-old child's vocabulary.
2. Describe everything clearly: subject, style, colors, composition, lighting, background, and camera view.
3. NEVER use marketing fluff like 'best for', 'ideal for', 'suitable for', or 'perfect for'.
4. NO complex words, NO jargon, NO unnecessary symbols.
5. Your output must be ONE full, detailed paragraph.
6. Only describe what is in the image to help recreate it.
7. Always output in English.
${settings.customInstruction ? `\nUser Instructions: ${settings.customInstruction}` : ''}`;

    const userPrompt = "Write a clear, simple English paragraph describing this image so an AI can recreate it.";

    const apiKeys = model.provider === 'gemini' ? [] : settings.apiKeys[model.provider as keyof typeof settings.apiKeys];

    return await this.executeWithRotation(model.provider, apiKeys, async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(model.id, userPrompt, data, mime, systemPrompt);
      }
      return await this.providerGenerate(model.provider, key, model.id, userPrompt, data, mime, systemPrompt);
    });
  }

  public static async refinePrompt(input: string, settings: Settings, model: Model) {
    const systemPrompt = `You are a professional prompt improver.
Take the user's idea and turn it into a high-quality, full paragraph prompt using simple English.
RULES:
1. Use simple English that a 10-year-old child can understand easily.
2. No marketing words, no complex jargon, no extra symbols.
3. Always output in English, even if the input is in another language.
4. Output ONE full, clear, descriptive paragraph.
${settings.customInstruction ? `\nUser Instructions: ${settings.customInstruction}` : ''}`;

    const apiKeys = model.provider === 'gemini' ? [] : settings.apiKeys[model.provider as keyof typeof settings.apiKeys];

    return await this.executeWithRotation(model.provider, apiKeys, async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(model.id, input, undefined, undefined, systemPrompt);
      }
      return await this.providerGenerate(model.provider, key, model.id, input, undefined, undefined, systemPrompt);
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    return [];
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, 
  Trash2, 
  Download, 
  Settings as SettingsIcon, 
  RotateCcw, 
  ChevronDown, 
  X, 
  Copy, 
  Check, 
  AlertCircle,
  ImagePlus,
  Loader2,
  FileCheck,
  Trophy,
  Play,
  Sparkles,
  Share2,
  LayoutGrid
} from 'lucide-react';
import { 
  PromptForgeImage, 
  Settings, 
  Model, 
  Provider
} from './types';
import { 
  INITIAL_MODELS, 
  DEFAULT_SETTINGS, 
  LOGO_SVG 
} from './constants';
import { AIService } from './services/aiService';

export default function App() {
  // --- State ---
  const [images, setImages] = useState<PromptForgeImage[]>([]);
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('prompt_forge_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      // Ensure gemini keys are not stored or managed manually
      if (parsed.apiKeys) {
        delete (parsed.apiKeys as any).gemini;
      }
      return parsed;
    }
    return DEFAULT_SETTINGS;
  });
  const [models, setModels] = useState<Model[]>(INITIAL_MODELS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [currentProcessingIndex, setCurrentProcessingIndex] = useState(0);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [activeModal, setActiveModal] = useState<'settings' | 'privacy' | 'faq' | null>(null);
  const [refineInput, setRefineInput] = useState('');
  const [refineOutput, setRefineOutput] = useState('');
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'error' | 'warning' } | null>(null);
  const [usageLimitError, setUsageLimitError] = useState<{ modelId: string; provider: Provider } | null>(null);

  const [groqInput, setGroqInput] = useState('');
  const [mistralInput, setMistralInput] = useState('');

  const [isDragging, setIsDragging] = useState(false);
  const [dropSuccess, setDropSuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // ROOT CAUSE MITIGATION: ref to track latest images state for async loop
  const imagesRef = useRef<PromptForgeImage[]>([]);
  useEffect(() => {
    imagesRef.current = images;
  }, [images]);

  useEffect(() => {
    setModels(INITIAL_MODELS);
    const preventDefault = (e: DragEvent) => e.preventDefault();
    window.addEventListener('dragover', preventDefault);
    window.addEventListener('drop', preventDefault);
    return () => {
      window.removeEventListener('dragover', preventDefault);
      window.removeEventListener('drop', preventDefault);
    };
  }, []);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3500);
  };

  const saveSettings = () => {
    localStorage.setItem('prompt_forge_settings', JSON.stringify(settings));
    showNotification("Settings saved.");
    setActiveModal(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();

    if (e.type === 'drop') {
      setIsDragging(false);
      setDropSuccess(true);
      setTimeout(() => setDropSuccess(false), 800);
    }

    let files: File[] = [];
    if (e.type === 'drop' && 'dataTransfer' in e && e.dataTransfer) {
      files = Array.from(e.dataTransfer.files);
    } else if (e.target instanceof HTMLInputElement && e.target.files) {
      files = Array.from(e.target.files);
    }

    const imageFiles = files.filter(file => file.type.startsWith('image/'));
    if (imageFiles.length === 0) return;

    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }

    const newImages: PromptForgeImage[] = imageFiles.map((file: File) => ({
      id: Math.random().toString(36).substring(2, 11) + Date.now(),
      file,
      previewUrl: URL.createObjectURL(file), 
      status: 'pending',
    }));

    setImages(prev => [...prev, ...newImages]);
  };

  const clearImages = () => {
    images.forEach(img => {
      if (img.previewUrl) URL.revokeObjectURL(img.previewUrl);
    });
    setImages([]);
    setGenerationProgress(0);
    setCurrentProcessingIndex(0);
    setIsGenerating(false);
    setIsPaused(false);
    setUsageLimitError(null);
    showNotification("Workspace cleared.", "success");
  };

  const generatePrompts = async () => {
    const totalToProcess = imagesRef.current.length;
    if (totalToProcess === 0) return showNotification("Please upload an image first.", "error");

    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];

    setIsGenerating(true);
    setIsPaused(false);
    setUsageLimitError(null);

    for (let i = currentProcessingIndex; i < totalToProcess; i++) {
      if (isPaused) break;

      const currentList = imagesRef.current;
      const currentImg = currentList[i];

      if (currentImg.status === 'completed') continue;

      const targetId = currentImg.id;
      setImages(prev => prev.map(img => img.id === targetId ? { ...img, status: 'processing', error: undefined } : img));

      try {
        const promptResult = await AIService.generatePromptFromImage(currentImg, settings, activeModel);

        if (!promptResult) throw new Error("Empty response from AI");

        const prefixes = settings.prefixes.slice(0, settings.prefixCount).join(' ');
        const suffixes = settings.suffixes.slice(0, settings.suffixCount).join(' ');
        const fullPrompt = `${prefixes} ${promptResult} ${suffixes}`.trim().replace(/\s+/g, ' ');

        setImages(prev => prev.map(img => img.id === targetId ? { 
          ...img, 
          status: 'completed', 
          prompt: fullPrompt 
        } : img));
      } catch (error: any) {
        console.error("Task error:", error);
        setImages(prev => prev.map(img => img.id === targetId ? { 
          ...img, 
          status: 'error', 
          error: error.message || "Unknown error"
        } : img));

        if (error.message.includes('EXHAUSTED') || error.message.includes('NO_KEYS')) {
          setUsageLimitError({ modelId: activeModel.id, provider: activeModel.provider });
          setIsGenerating(false);
          setIsPaused(true);
          showNotification(`Provider ${activeModel.provider} is currently unavailable.`, "error");
          break; 
        }
      }

      const nextIndex = i + 1;
      setCurrentProcessingIndex(nextIndex);
      setGenerationProgress((nextIndex / totalToProcess) * 100);
    }

    setIsGenerating(false);
  };

  const refinePromptAction = async () => {
    if (!refineInput) return;
    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];

    try {
      setIsGenerating(true);
      const refined = await AIService.refinePrompt(refineInput, settings, activeModel);
      setRefineOutput(refined || "");
    } catch (error: any) {
      showNotification(`Refinement failed: ${error.message}`, "error");
    } finally {
      setIsGenerating(false);
    }
  };

  // Fixed exportCSV function
  const exportCSV = () => {
    const currentList = imagesRef.current;
    const completed = currentList.filter(img => img.status === 'completed');

    if (completed.length === 0) {
      return showNotification("No completed prompts to export.", "warning");
    }

    const BOM = '\uFEFF';
    const header = "SL No,Prompt\r\n";

    // Fixed line 251: properly mapping images and sanitizing CSV output
    const rows = completed.map((img, index) => {
      const sanitizedPrompt = img.prompt?.replace(/"/g, '""') || "";
      return `${index + 1},"${sanitizedPrompt}"`;
    }).join("\r\n");

    const csvContent = BOM + header + rows;
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `prompt_forge_export_${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showNotification(`Exported ${completed.length} prompts.`, "success");
  };

  const removeImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
    showNotification("Image removed.", "warning");
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    showNotification("Copied to clipboard!");
  };

  return (
    <div className={`min-h-screen ${settings.theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'} font-sans`}>
      {/* Header */}
      <header className="border-b border-slate-800/50 backdrop-blur-md sticky top-0 z-40 bg-slate-950/80 px-6 py-4 flex items-center justify-between">
        <div className="flex items-center">
          {LOGO_SVG}
          <h1 className="text-xl font-bold bg-gradient-to-r from-violet-400 to-fuchsia-400 bg-clip-text text-transparent">
            Prompt Forge
          </h1>
        </div>

        <div className="flex items-center gap-4">
          <select 
            value={settings.preferredModel}
            onChange={(e) => setSettings({...settings, preferredModel: e.target.value})}
            className="bg-slate-900 border border-slate-800 rounded-lg px-3 py-1.5 text-sm outline-none focus:ring-2 focus:ring-violet-500/50 transition-all"
          >
            {models.map(m => (
              <option key={m.id} value={m.id}>{m.name}</option>
            ))}
          </select>

          <button 
            onClick={() => setActiveModal('settings')}
            className="p-2 hover:bg-slate-800 rounded-full transition-colors"
          >
            <SettingsIcon size={20} className="text-slate-400" />
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto p-6 space-y-8">
        {/* Upload Area */}
        <div 
          onDragOver={() => setIsDragging(true)}
          onDragLeave={() => setIsDragging(false)}
          onDrop={handleFileUpload}
          className={`
            relative border-2 border-dashed rounded-2xl p-12 text-center transition-all cursor-pointer
            ${isDragging ? 'border-violet-500 bg-violet-500/5' : 'border-slate-800 hover:border-slate-700 bg-slate-900/30'}
            ${dropSuccess ? 'scale-[0.98] border-emerald-500 bg-emerald-500/5' : ''}
          `}
          onClick={() => fileInputRef.current?.click()}
        >
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            multiple 
            accept="image/*" 
            onChange={handleFileUpload}
          />
          <div className="flex flex-col items-center gap-4">
            <div className="p-4 bg-violet-500/10 rounded-full text-violet-400">
              <ImagePlus size={32} />
            </div>
            <div>
              <p className="text-lg font-medium">Drop images here or click to upload</p>
              <p className="text-slate-500 text-sm mt-1">Supports PNG, JPG, WEBP (Batch processing enabled)</p>
            </div>
          </div>
        </div>

        {/* Controls */}
        <div className="flex flex-wrap items-center justify-between gap-4 bg-slate-900/50 p-4 rounded-xl border border-slate-800/50">
          <div className="flex items-center gap-3">
            <button 
              onClick={generatePrompts}
              disabled={isGenerating || images.length === 0}
              className="flex items-center gap-2 px-6 py-2 bg-violet-600 hover:bg-violet-500 disabled:opacity-50 disabled:hover:bg-violet-600 text-white rounded-lg font-medium transition-all shadow-lg shadow-violet-500/20"
            >
              {isGenerating ? <Loader2 className="animate-spin" size={18} /> : <Play size={18} />}
              {currentProcessingIndex > 0 ? 'Resume' : 'Start Processing'}
            </button>
            <button 
              onClick={clearImages}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-lg font-medium transition-all"
            >
              <RotateCcw size={18} />
              Reset Workspace
            </button>
          </div>

          <button 
            onClick={exportCSV}
            className="flex items-center gap-2 px-4 py-2 border border-slate-700 hover:border-slate-600 text-slate-300 rounded-lg font-medium transition-all"
          >
            <Download size={18} />
            Export CSV
          </button>
        </div>

        {/* Progress Bar */}
        {isGenerating && (
          <div className="space-y-2">
            <div className="flex justify-between text-xs text-slate-400 font-medium px-1">
              <span>Processing: {currentProcessingIndex} / {images.length}</span>
              <span>{Math.round(generationProgress)}%</span>
            </div>
            <div className="h-2 bg-slate-900 rounded-full overflow-hidden border border-slate-800">
              <div 
                className="h-full bg-gradient-to-r from-violet-500 to-fuchsia-500 transition-all duration-500 ease-out"
                style={{ width: `${generationProgress}%` }}
              />
            </div>
          </div>
        )}

        {/* Workspace Gallery */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {images.map((img) => (
            <div key={img.id} className="group relative bg-slate-900 rounded-xl border border-slate-800 overflow-hidden hover:border-slate-700 transition-all">
              <div className="aspect-video relative overflow-hidden bg-slate-950">
                <img src={img.previewUrl} alt="Preview" className="w-full h-full object-cover" />

                {/* Status Overlay */}
                <div className="absolute top-3 right-3 flex gap-2">
                  {img.status === 'processing' && (
                    <div className="bg-violet-600/90 text-white p-1.5 rounded-full animate-pulse shadow-lg">
                      <Loader2 size={16} className="animate-spin" />
                    </div>
                  )}
                  {img.status === 'completed' && (
                    <div className="bg-emerald-600/90 text-white p-1.5 rounded-full shadow-lg">
                      <FileCheck size={16} />
                    </div>
                  )}
                  {img.status === 'error' && (
                    <div className="bg-rose-600/90 text-white p-1.5 rounded-full shadow-lg">
                      <AlertCircle size={16} />
                    </div>
                  )}
                  <button 
                    onClick={() => removeImage(img.id)}
                    className="bg-slate-950/80 text-white p-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-opacity hover:bg-rose-600"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              <div className="p-4 space-y-3">
                {img.status === 'completed' ? (
                  <div className="space-y-2">
                    <p className="text-sm text-slate-300 line-clamp-4 leading-relaxed italic">
                      "{img.prompt}"
                    </p>
                    <button 
                      onClick={() => copyToClipboard(img.prompt || "")}
                      className="flex items-center gap-1.5 text-xs text-violet-400 hover:text-violet-300 font-medium transition-colors"
                    >
                      <Copy size={12} />
                      Copy Prompt
                    </button>
