import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

/**
 * Optimized Image Processor
 * Reduces payload size by resizing and compressing images before sending to vision APIs.
 * This drastically reduces network upload time and improves Groq's processing speed.
 */
const prepareImage = (file: File, maxDim: number): Promise<{data: string, mime: string}> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        // Lower quality (0.5-0.6) for faster upload/processing without losing AI comprehension
        const dataUrl = canvas.toDataURL('image/jpeg', maxDim < 600 ? 0.5 : 0.6);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

// Global state for key rotation indices
const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  /**
   * Universal key manager. Handles rotation and error detection.
   */
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      if (provider === 'gemini' && typeof process !== 'undefined' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY);
      }
      throw new Error(`NO_KEYS_CONFIGURED_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    let lastError = "";

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        lastError = error.message;
        console.warn(`[${provider}] Key attempt failed. Rotating...`);
        attempts++;
      }
    }

    throw new Error(`PROVIDER_FAILURE_${provider.toUpperCase()}: ${lastError}`);
  }

  /**
   * Speed-Optimized Retry Strategy.
   */
  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 5): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = e.message?.toLowerCase() || "";

      if (err.includes("401") || err.includes("unauthorized") || err.includes("invalid api key") || err.includes("auth")) {
        throw e;
      }

      if (retries > 0) {
        // Fast backoff
        const delay = 100 + (Math.random() * 100);
        await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    apiKey: string,
    modelId: string, 
    prompt: string, 
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const ai = new GoogleGenAI({ apiKey });

    const parts: any[] = [{ text: prompt }];
    if (base64Data && mimeType) {
      parts.unshift({
        inlineData: {
          mimeType: mimeType,
          data: base64Data
        }
      });
    }

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });

    return response.text;
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';

    let actualModelId = modelId;
    let temperature = 0.7;
    let maxTokens = 512;
    let timeout = 20000;

    if (provider === 'groq') {
      if (modelId === 'llama-4-scout-fast') {
        actualModelId = 'llama-3.2-11b-vision-preview';
        temperature = 0.0; // Greedy decoding for maximum speed
        maxTokens = 256; // Short tokens for fast descriptive paragraph
        timeout = 10000;
      } else if (modelId === 'llama-4-maverick-hq') {
        actualModelId = 'llama-3.2-90b-vision-preview';
        temperature = 0.0;
        maxTokens = 384; 
        timeout = 15000;
      }
    } else if (provider === 'mistral') {
      if (modelId === 'pixtral-12b-vision') {
        actualModelId = 'pixtral-12b-2409';
        temperature = 0.2;
        maxTokens = 400;
      }
    }

    const messages: any[] = [];
    if (systemInstruction) {
      messages.push({ role: 'system', content: systemInstruction });
    }

    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { 
            type: 'image_url', 
            image_url: { url: `data:${mimeType};base64,${base64Data}` } 
          }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout); 

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey.trim()}`
        },
        body: JSON.stringify({
          model: actualModelId,
          messages,
          temperature,
          max_tokens: maxTokens,
          stream: false
        }),
        signal: controller.signal
      });

      if (!response.ok) {
        const textResponse = await response.text();
        throw new Error(textResponse || `HTTP ${response.status}`);
      }

      const data = await response.json();
      return data.choices?.[0]?.message?.content || "";
    } finally {
      clearTimeout(timeoutId);
    }
  }

  public static async generatePromptFromImage(
    image: PromptForgeImage,
    settings: Settings,
    model: Model
  ) {
    if (!model.hasVision) throw new Error("Model not vision-capable.");

    // PERF: Smaller images process significantly faster on Groq LPUs.
    let maxDim = 800;
    if (model.id === 'llama-4-scout-fast') maxDim = 512;
    else if (model.id === 'pixtral-12b-vision') maxDim = 640;

    const { data, mime } = await prepareImage(image.file, maxDim);

    const systemPrompt = `You are a professional stock photography prompt engineer. 
    Analyze the image and extract a rich, detailed, stock-ready prompt.
    Output: ONE CLEAR PARAGRAPH. No bullets. No symbols. English only.
    ${settings.customInstruction ? `\nGlobal Instruction: ${settings.customInstruction}` : ''}`;

    const userPrompt = "Generate a professional image prompt for this visual content.";

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, userPrompt, data, mime, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, userPrompt, data, mime, systemPrompt);
      }
    });
  }

  public static async refinePrompt(
    input: string,
    settings: Settings,
    model: Model
  ) {
    const systemPrompt = `Refine the user's prompt into a powerful, professional English prompt paragraph.
    Output: One descriptive paragraph. No bullets.
    ${settings.customInstruction ? `\nGlobal Instruction: ${settings.customInstruction}` : ''}`;

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, input, undefined, undefined, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, input, undefined, undefined, systemPrompt);
      }
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    return [];
  }
}

