import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

/**
 * High-Speed Image Preprocessor
 * Downscales images to model-specific optimal resolutions to minimize upload latency and LPU processing time.
 */
const prepareImage = (file: File, maxDim: number): Promise<{data: string, mime: string}> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'low'; // Faster scaling
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        // Drastically reduced quality (0.4) for Scout-Fast to hit sub-second processing
        const quality = maxDim <= 512 ? 0.4 : 0.6;
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      if (provider === 'gemini' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY);
      }
      throw new Error(`NO_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();
      if (!currentKey) { attempts++; continue; }

      try {
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        attempts++;
      }
    }
    throw new Error(`PROVIDER_FAILURE_${provider.toUpperCase()}`);
  }

  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 3): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      if (retries > 0) {
        await new Promise(r => setTimeout(r, 100));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    apiKey: string,
    modelId: string, 
    prompt: string, 
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const ai = new GoogleGenAI({ apiKey });
    const parts: any[] = [{ text: prompt }];
    if (base64Data && mimeType) {
      parts.unshift({ inlineData: { mimeType, data: base64Data } });
    }

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { 
        systemInstruction, 
        temperature: 0.1, // Lower temperature = faster, more predictable output
        maxOutputTokens: 256 
      }
    });

    return response.text || "";
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';
    let actualModelId = modelId;
    let temperature = 0.0; // Greedy decoding for Groq/Mistral is nearly instantaneous
    let maxTokens = 200;

    if (provider === 'groq') {
      if (modelId === 'llama-4-scout-fast') actualModelId = 'llama-3.2-11b-vision-preview';
      else if (modelId === 'llama-4-maverick-hq') actualModelId = 'llama-3.2-90b-vision-preview';
    } else if (provider === 'mistral') {
      if (modelId === 'pixtral-12b-vision') actualModelId = 'pixtral-12b-2409';
      temperature = 0.1;
    }

    const messages: any[] = [];
    if (systemInstruction) messages.push({ role: 'system', content: systemInstruction });
    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey.trim()}`
      },
      body: JSON.stringify({
        model: actualModelId,
        messages,
        temperature,
        max_tokens: maxTokens,
        stream: false
      })
    });

    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    return data.choices?.[0]?.message?.content || "";
  }

  public static async generatePromptFromImage(image: PromptForgeImage, settings: Settings, model: Model) {
    // Scout-Fast uses 512px for lightning speed, Maverick/Pixtral use higher res for accuracy.
    let maxDim = 800;
    if (model.id === 'llama-4-scout-fast') maxDim = 512;
    else if (model.provider === 'mistral') maxDim = 640;

    const { data, mime } = await prepareImage(image.file, maxDim);

    const systemPrompt = `You are a professional image prompt engineer. Describe this image in one detailed, simple English paragraph. NO BULLETS. NO SYMBOLS. ONLY ENGLISH. 
    ${settings.customInstruction ? `\nInstructions: ${settings.customInstruction}` : ''}`;

    const userPrompt = "Write a clear paragraph describing this image for an AI generator.";

    const result = await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') return await this.geminiGenerate(key, model.id, userPrompt, data, mime, systemPrompt);
      return await this.providerGenerate(model.provider, key, model.id, userPrompt, data, mime, systemPrompt);
    });

    if (!result || result.trim().length < 5) throw new Error("AI_EMPTY_RESPONSE");
    return result.trim();
  }

  public static async refinePrompt(input: string, settings: Settings, model: Model) {
    const systemPrompt = `Improve this prompt idea into a professional paragraph. Simple English. 
    ${settings.customInstruction ? `\nInstructions: ${settings.customInstruction}` : ''}`;

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') return await this.geminiGenerate(key, model.id, input, undefined, undefined, systemPrompt);
      return await this.providerGenerate(model.provider, key, model.id, input, undefined, undefined, systemPrompt);
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> { return []; }
}

