          <div 
            className={`relative group p-16 lg:p-24 border-2 border-dashed rounded-[2.5rem] text-center glass-card transition-all duration-500 cursor-pointer overflow-hidden premium-shadow ${isDragging ? 'border-violet-400 bg-violet-500/10 scale-[1.01] shadow-[0_0_50px_rgba(139,92,246,0.2)]' : 'border-white/10 hover:border-violet-500/40'} ${dropSuccess ? 'ring-4 ring-emerald-500/20 border-emerald-500/40 bg-emerald-500/5' : ''}`}
            onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); setIsDragging(true); }}
