                </div>
                {!isGenerating && (
                  <button onClick={(e) => { e.stopPropagation(); clearImages(); }} className="ml-4 p-2.5 hover:bg-rose-500/20 text-slate-500 hover:text-rose-400 rounded-xl transition-all"><Trash2 size={18} /></button>
