          {/* Processing Details */}
          {isGenerating && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-500 space-y-8 max-w-2xl mx-auto py-10 px-8 glass-card rounded-[2.5rem] border-violet-500/20 bg-violet-500/5">
              <div className="text-center space-y-3">
                <div className="w-16 h-16 bg-violet-500/10 rounded-full flex items-center justify-center mx-auto mb-4 border border-violet-500/20 relative"><Loader2 size={32} className="text-violet-400 animate-spin" /><div className="absolute -top-1 -right-1 w-4 h-4 bg-fuchsia-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(217,70,239,0.5)]" /></div>
                <h3 className="text-2xl font-black text-white tracking-tight">Forging Prompts...</h3>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-[0.2em] animate-pulse">Running batch sequence...</p>
              </div>
              <div className="space-y-4">
                <div className="flex justify-between text-[10px] font-black text-slate-500 uppercase tracking-widest"><span>Current Task: {currentProcessingIndex + 1} of {images.length}</span><span>{Math.round(generationProgress)}% Complete</span></div>
                <div className="w-full h-4 bg-slate-950/50 rounded-full overflow-hidden p-1 border border-white/5"><div className="h-full bg-gradient-to-r from-violet-500 via-fuchsia-500 to-indigo-500 rounded-full transition-all duration-700" style={{ width: `${generationProgress}%` }} /></div>
              </div>
            </div>
          )}

          {/* Batch Completed card */}
          {allFinished && !isGenerating && !isPaused && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000 flex flex-col items-center gap-10">
              <div className="glass-card w-full max-w-2xl p-12 rounded-[3rem] border-fuchsia-500/20 bg-fuchsia-500/5 text-center space-y-6 premium-shadow relative overflow-hidden">
                <div className="absolute -top-10 -right-10 p-6 opacity-5 rotate-12 pointer-events-none"><Trophy size={180} /></div>
                <div className="w-20 h-20 bg-fuchsia-500/10 rounded-[2rem] flex items-center justify-center mx-auto mb-6 border border-fuchsia-500/20"><Check size={40} className="text-fuchsia-400" /></div>
                <div className="space-y-2">
                  <h3 className="text-3xl font-black text-white tracking-tight">Batch Completed</h3>
                  <p className="text-slate-400 font-medium text-lg text-balance">Export your prompts to CSV to view results.</p>
                </div>
                <div className="pt-6 flex flex-col items-center">
                  <button onClick={exportCSV} className="w-full py-6 px-12 rounded-[1.5rem] bg-white text-slate-950 hover:bg-slate-200 font-black text-xl transition-all flex items-center justify-center gap-4 premium-shadow active:scale-[0.98]"><Download size={28} className="text-fuchsia-600" />Download CSV List</button>
                  {/* RESTORED: Clear Workspace button under CSV download */}
                  <button onClick={clearImages} className="mt-6 text-sm font-bold text-slate-500 hover:text-rose-400 transition-colors flex items-center gap-2">
                    <RotateCcw size={16} /> Clear Your Workspace Data
                  </button>
                </div>
              </div>
            </div>
          )}

          {!isGenerating && (
            <div className="flex flex-col sm:flex-row gap-5 max-w-2xl mx-auto">
              <button onClick={() => fileInputRef.current?.click()} className="flex-1 py-5 px-10 rounded-[1.5rem] bg-slate-900 hover:bg-slate-800 text-white font-black text-lg transition-all flex items-center justify-center gap-3 border border-white/10 hover:border-white/20 premium-shadow"><ImagePlus size={24} className="text-violet-400" />Add Images</button>
              <button onClick={generatePrompts} disabled={images.length === 0} className={`flex-1 py-5 px-10 rounded-[1.5rem] font-black text-lg shadow-2xl transition-all active:scale-[0.98] flex items-center justify-center gap-3 ${images.length === 0 ? 'bg-slate-900 text-slate-600 cursor-not-allowed border border-white/5' : 'bg-white text-slate-950 hover:bg-slate-200 premium-shadow'}`}>
                {isPaused ? <Play size={24} className="text-emerald-600" /> : <Sparkles size={24} className="text-violet-600" />}{isPaused ? 'Resume Processing' : 'Start Creating'}
              </button>
            </div>
          )}
        </section>

        {/* Refiner */}
        <section className="space-y-10 relative">
          <div className="absolute -top-24 -left-24 w-64 h-64 bg-fuchsia-500/10 blur-[100px] pointer-events-none" />
          <div className="flex items-center gap-4 mb-2"><div className="p-3 bg-fuchsia-500/10 rounded-2xl"><LayoutGrid size={24} className="text-fuchsia-400" /></div><div><h2 className="text-3xl font-black tracking-tight text-white">Prompt Improver</h2><p className="text-slate-500 font-medium">Make your prompt ideas look better.</p></div></div>
          <div className="glass-card rounded-[2.5rem] p-1.5 premium-shadow">
            <div className="p-8 lg:p-10 space-y-6">
              <textarea value={refineInput} onChange={(e) => setRefineInput(e.target.value)} placeholder="Paste your prompt ideas here..." className="w-full h-48 bg-slate-950/50 rounded-3xl p-8 text-lg text-slate-100 placeholder-slate-600 border border-white/5 focus:border-fuchsia-500/50 focus:ring-4 focus:ring-fuchsia-500/5 outline-none transition-all resize-none font-medium leading-relaxed" />
              <button onClick={refinePromptAction} disabled={isGenerating || !refineInput} className="w-full py-5 bg-gradient-to-r from-fuchsia-600 to-violet-600 hover:from-fuchsia-500 hover:to-violet-500 disabled:bg-slate-900 disabled:from-transparent disabled:to-transparent disabled:text-slate-700 text-white font-black text-lg rounded-[1.5rem] transition-all flex items-center justify-center gap-3 premium-shadow active:scale-[0.99]">{isGenerating ? <RotateCcw size={22} className="animate-spin" /> : <Sparkles size={22} />}Improve Prompt</button>
              {refineOutput && (
                <div className="mt-12 animate-in fade-in zoom-in-95 duration-500">
                  <div className="flex items-center justify-between mb-4"><span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">New Prompt</span><button onClick={() => copyToClipboard(refineOutput)} className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full text-xs font-bold text-slate-300 transition-all border border-white/5"><Copy size={14} />Copy</button></div>
                  <div className="p-10 bg-gradient-to-br from-violet-500/[0.08] to-fuchsia-500/[0.08] border border-white/5 rounded-3xl relative overflow-hidden"><div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none"><Sparkles size={120} /></div><p className="text-xl lg:text-2xl leading-[1.6] text-slate-100 font-semibold italic text-balance">"{refineOutput}"</p></div>
                </div>
