        {/* Logic Managers */}
        <section className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="space-y-6">
            <div className="flex items-center gap-3 px-2"><Layers size={20} className="text-indigo-400" /><h2 className="text-xl font-black text-white uppercase tracking-wider">Add to Start</h2></div>
            <div className="glass-card p-10 rounded-[2.5rem] space-y-8 premium-shadow min-h-[340px] flex flex-col">
              <input type="text" placeholder="Type a word and press Enter..." onKeyDown={(e) => { if (e.key === 'Enter') { const val = (e.target as HTMLInputElement).value.trim(); if (val && !settings.prefixes.includes(val)) { setSettings({ ...settings, prefixes: [...settings.prefixes, val] }); (e.target as HTMLInputElement).value = ''; } } }} className="w-full bg-slate-950/50 border border-white/5 rounded-2xl px-6 py-4 text-sm font-semibold outline-none focus:border-indigo-500/50 transition-all placeholder-slate-600" />
              <div className="space-y-4"><div className="flex items-center justify-between text-[11px] font-black text-slate-500 uppercase tracking-widest px-1"><span>How many words to use: {settings.prefixCount}</span></div><input type="range" min="0" max={settings.prefixes.length} value={settings.prefixCount} onChange={(e) => setSettings({ ...settings, prefixCount: parseInt(e.target.value) })} className="w-full h-1.5 bg-white/5 rounded-lg appearance-none cursor-pointer accent-indigo-500" /></div>
              <div className="flex flex-wrap gap-2.5 flex-grow content-start">{settings.prefixes.length === 0 && <p className="text-xs font-bold text-slate-600 italic">No words added yet.</p>}{settings.prefixes.map((p, i) => (<span key={i} className={`px-4 py-2 rounded-xl text-xs font-bold flex items-center transition-all duration-300 ${i < settings.prefixCount ? 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/30 shadow-lg shadow-indigo-500/10' : 'bg-slate-900 text-slate-600 border border-white/5'}`}>{p}<button onClick={() => setSettings({ ...settings, prefixes: settings.prefixes.filter((_, idx) => idx !== i) })} className="ml-3 hover:text-white transition-colors"><X size={12} /></button></span>))}</div>
            </div>
          </div>
          <div className="space-y-6">
            <div className="flex items-center gap-3 px-2"><Layers size={20} className="text-amber-400 rotate-180" /><h2 className="text-xl font-black text-white uppercase tracking-wider">Add to End</h2></div>
