              <div className="flex flex-wrap gap-2.5 flex-grow content-start">{settings.suffixes.length === 0 && <p className="text-xs font-bold text-slate-600 italic">No words added yet.</p>}{settings.suffixes.map((s, i) => (<span key={i} className={`px-4 py-2 rounded-xl text-xs font-bold flex items-center transition-all duration-300 ${i < settings.suffixCount ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30 shadow-lg shadow-amber-500/10' : 'bg-slate-900 text-slate-600 border border-white/5'}`}>{s}<button onClick={() => setSettings({ ...settings, suffixes: settings.suffixes.filter((_, idx) => idx !== i) })} className="ml-3 hover:text-white transition-colors"><X size={12} /></button></span>))}</div>
