      return parsed;
    }
    return DEFAULT_SETTINGS;
  });
  const [models, setModels] = useState<Model[]>(INITIAL_MODELS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [currentProcessingIndex, setCurrentProcessingIndex] = useState(0);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [activeModal, setActiveModal] = useState<'hub' | 'settings' | 'privacy' | 'terms' | 'faq' | 'contact' | null>(null);
  const [refineInput, setRefineInput] = useState('');
  const [refineOutput, setRefineOutput] = useState('');
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'error' | 'warning' } | null>(null);
  const [usageLimitError, setUsageLimitError] = useState<{ modelId: string; provider: Provider } | null>(null);
  const [expandedFaq, setExpandedFaq] = useState<number | null>(null);

  const [geminiInput, setGeminiInput] = useState('');
  const [groqInput, setGroqInput] = useState('');
  const [mistralInput, setMistralInput] = useState('');

  const [isDragging, setIsDragging] = useState(false);
  const [dropSuccess, setDropSuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imagesRef = useRef<PromptForgeImage[]>([]);

  const faqData = [
    { q: "What is Prompt Forge?", a: "Prompt Forge is an AI-powered tool that helps you turn images into detailed and accurate prompts. It is built for creators and microstock contributors who want high-quality prompts for generating similar images using AI tools." },
    { q: "How does the image to prompt feature work?", a: "You upload one or more images, and Prompt Forge analyzes each image to understand details like subject, style, lighting, and composition." },
    { q: "Do I need my own API keys to use Prompt Forge?", a: "Yes, Prompt Forge uses your own API keys for supported AI models. This gives you full control over usage, limits, and model selection." },
    { q: "Which AI models are supported?", a: "Prompt Forge supports multiple AI providers including Google Gemini models, Groq models, and Mistral AI models." },
    { q: "Are my images stored on your servers?", a: "No. Uploaded images are used only for generating prompts. Images are not permanently stored and are removed when the session ends or when the user clears data." },
    { q: "Can I download my prompts?", a: "Yes. Generated prompts can be downloaded as a CSV file, making it easy to upload and reuse them for stock or AI workflows." }
  ];

  useEffect(() => {
    setModels(INITIAL_MODELS);
    const preventDefault = (e: DragEvent) => e.preventDefault();
    window.addEventListener('dragover', preventDefault);
    window.addEventListener('drop', preventDefault);
    return () => {
      window.removeEventListener('dragover', preventDefault);
      window.removeEventListener('drop', preventDefault);
    };
  }, []);

  useEffect(() => {
    imagesRef.current = images;
  }, [images]);

  const showNotification = (message: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3500);
  };

  const saveSettings = () => {
    localStorage.setItem('prompt_forge_settings', JSON.stringify(settings));
    showNotification("Settings saved.");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();

    if (e.type === 'drop') {
      setIsDragging(false);
      setDropSuccess(true);
      setTimeout(() => setDropSuccess(false), 800);
    }

    let files: File[] = [];
    if (e.type === 'drop' && 'dataTransfer' in e && e.dataTransfer) {
      files = Array.from(e.dataTransfer.files);
    } else if (e.target instanceof HTMLInputElement && e.target.files) {
      files = Array.from(e.target.files);
    }

    const imageFiles = files.filter(file => file.type.startsWith('image/'));
    if (imageFiles.length === 0) return;

    if (fileInputRef.current) fileInputRef.current.value = '';

    const newImages: PromptForgeImage[] = imageFiles.map((file: File) => ({
      id: Math.random().toString(36).substring(2, 11) + Date.now(),
      file,
      previewUrl: URL.createObjectURL(file), 
      status: 'pending',
    }));

    setImages(prev => [...prev, ...newImages]);
  };

  const clearImages = () => {
    images.forEach(img => {
      if (img.previewUrl) URL.revokeObjectURL(img.previewUrl);
    });
    setImages([]);
    setGenerationProgress(0);
    setCurrentProcessingIndex(0);
    setIsGenerating(false);
    setIsPaused(false);
    setUsageLimitError(null);
    showNotification("All data cleared.", "success");
  };

  const generatePrompts = async () => {
    if (imagesRef.current.length === 0) return showNotification("Please upload an image first.", "error");

    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    const keys = settings.apiKeys[activeModel.provider];

    if (keys.length === 0 && !(activeModel.provider === 'gemini' && process.env.API_KEY)) {
      return showNotification(`Please add at least one API key for ${activeModel.provider} in settings.`, "error");
    }

    setIsGenerating(true);
    setIsPaused(false);
    setUsageLimitError(null);

    let i = currentProcessingIndex;
    while (i < imagesRef.current.length) {
      const currentImg = imagesRef.current[i];
      if (currentImg.status === 'completed' || currentImg.status === 'processing') {
        i++;
        continue;
      }

      const targetId = currentImg.id;
      try {
        setImages(prev => prev.map(img => img.id === targetId ? { ...img, status: 'processing' } : img));

        let promptResult = await AIService.generatePromptFromImage(currentImg, settings, activeModel);

        const prefixes = settings.prefixes.slice(0, settings.prefixCount).join(' ');
        const suffixes = settings.suffixes.slice(0, settings.suffixCount).join(' ');
        const fullPrompt = `${prefixes} ${promptResult} ${suffixes}`.trim().replace(/\s+/g, ' ');

        setImages(prev => prev.map(img => img.id === targetId ? { ...img, status: 'completed', prompt: fullPrompt } : img));
        setCurrentProcessingIndex(i + 1);
      } catch (error: any) {
        if (error.message.includes('EXHAUSTED')) {
          setUsageLimitError({ modelId: activeModel.id, provider: activeModel.provider });
          setIsGenerating(false);
          setIsPaused(true);
          showNotification(`Pool exhausted for ${activeModel.provider}.`, "error");
          return;
        }
        setImages(prev => prev.map(img => img.id === targetId ? { ...img, status: 'error', error: error.message } : img));
        setCurrentProcessingIndex(i + 1);
      }

      setGenerationProgress(((i + 1) / imagesRef.current.length) * 100);
      i++;
    }

    setIsGenerating(false);
    setIsPaused(false);
  };

  const refinePromptAction = async () => {
    if (!refineInput) return;
    const activeModel = models.find(m => m.id === settings.preferredModel) || models[0];
    try {
      setIsGenerating(true);
      const refined = await AIService.refinePrompt(refineInput, settings, activeModel);
      setRefineOutput(refined);
    } catch (error: any) {
      showNotification(`Refine failed: ${error.message}`, "error");
    } finally {
      setIsGenerating(false);
    }
  };

  const exportCSV = () => {
    // Column Headers: SL No., Prompt
    const header = "SL No.,Prompt\n";

    // Filter to only include completed prompts to avoid empty cells
    const completedList = images.filter(img => img.status === 'completed');

    if (completedList.length === 0) {
      showNotification("No prompts to export yet.", "warning");
      return;
    }

    // Escape and wrap prompt text to prevent column splitting
    const rows = completedList.map((img, i) => {
      // Standard CSV escaping: Double the existing double quotes
      // Wrap the entire field in double quotes to handle commas, newlines, and spacing
      const escapedPrompt = (img.prompt || "").replace(/"/g, '""');
      return `${i + 1},"${escapedPrompt}"`;
    }).join('\n');

    // Create and download blob with BOM for Excel compatibility
    const BOM = "\uFEFF";
    const blob = new Blob([BOM + header + rows], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `my_prompts_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    showNotification("CSV downloaded successfully!");
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    showNotification("Copied!");
  };

  const handleAddKey = (provider: Provider, key: string) => {
    if (!key.trim()) return;
    setSettings(prev => ({
      ...prev,
      apiKeys: { ...prev.apiKeys, [provider]: [...prev.apiKeys[provider], key.trim()] }
    }));
    if (provider === 'gemini') setGeminiInput('');
    else if (provider === 'groq') setGroqInput('');
    else if (provider === 'mistral') setMistralInput('');
  };

  const handleDeleteKey = (provider: Provider, index: number) => {
    setSettings(prev => ({
      ...prev,
      apiKeys: { ...prev.apiKeys, [provider]: prev.apiKeys[provider].filter((_, i) => i !== index) }
    }));
  };

  const hasImages = images.length > 0;
  const allFinished = hasImages && images.every(img => img.status === 'completed' || img.status === 'error');

  return (
    <div className={`min-h-screen transition-colors duration-300 ${settings.theme === 'light' ? 'bg-slate-50 text-slate-900' : 'bg-[#020617] text-slate-200'}`}>
      <div className="fixed inset-0 pointer-events-none gradient-bg -z-10" />

      {/* Header */}
      <header className="sticky top-0 z-40 backdrop-blur-xl border-b border-white/5 px-6 py-4">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center group cursor-default">
            <div className="transform group-hover:scale-110 transition-transform duration-500">{LOGO_SVG}</div>
            <div>
              <h1 className="text-xl md:text-2xl font-extrabold tracking-tight text-white">
                Prompt <span className="bg-clip-text text-transparent bg-gradient-to-r from-violet-400 via-fuchsia-400 to-indigo-400">Forge</span>
              </h1>
              <p className="text-[10px] uppercase tracking-[0.15em] text-slate-500 font-bold">Make Better Prompts For Real Result</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <button onClick={() => setActiveModal('settings')} className={`px-5 py-2.5 rounded-full transition-all border group flex items-center text-sm font-bold ${activeModal === 'settings' ? 'bg-violet-500/10 border-violet-500/30 text-violet-400' : 'glass-card hover:bg-white/10 text-slate-200 border-white/10'}`}>
              <SettingsIcon size={20} className="mr-2 group-hover:rotate-45 transition-transform" /> Settings
            </button>
            <button onClick={() => setActiveModal(activeModal === 'hub' ? null : 'hub')} className={`hidden sm:flex px-5 py-2.5 rounded-full transition-all text-sm font-bold border ${activeModal === 'hub' ? 'bg-violet-500/10 border-violet-500/30 text-violet-400 shadow-[0_0_20px_rgba(139,92,246,0.15)]' : 'glass-card hover:bg-white/10 text-slate-200 border-white/10'}`}>
              <Share2 size={16} className={`mr-2 transition-transform duration-300 ${activeModal === 'hub' ? 'scale-110' : ''}`} /> Community
            </button>
            <button onClick={() => setActiveModal(activeModal === 'contact' ? null : 'contact')} className={`hidden sm:flex px-5 py-2.5 rounded-full transition-all text-sm font-bold border ${activeModal === 'contact' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.15)]' : 'glass-card hover:bg-white/10 text-slate-200 border-white/10'}`}>Contact</button>
          </div>
        </div>
      </header>

      {/* Usage Limit Banner */}
      {usageLimitError && (
        <div className="bg-amber-500/10 border-b border-amber-500/20 px-6 py-3 text-center animate-in slide-in-from-top duration-300">
          <p className="text-amber-300 text-sm font-semibold flex items-center justify-center">
            <AlertCircle size={16} className="mr-2" /> Limit reached for {usageLimitError.modelId} pool.
            <button onClick={() => setActiveModal('settings')} className="ml-4 px-3 py-1 bg-amber-500/20 hover:bg-amber-500/30 rounded-full text-xs transition-all font-bold">Update Key Pool</button>
          </p>
        </div>
      )}

      {/* Notifications */}
      {notification && (
        <div className={`fixed bottom-10 left-1/2 -translate-x-1/2 z-50 px-6 py-3.5 rounded-2xl shadow-2xl flex items-center border backdrop-blur-md animate-in slide-in-from-bottom-8 fade-in duration-500 ${notification.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : notification.type === 'error' ? 'bg-rose-500/10 border-rose-500/20 text-rose-400' : 'bg-amber-500/10 border-amber-500/20 text-amber-400'}`}>
          {notification.type === 'success' ? <Check size={18} className="mr-3" /> : <AlertCircle size={18} className="mr-3" />}
          <span className="font-semibold text-sm">{notification.message}</span>
        </div>
      )}

      <main className="max-w-6xl mx-auto px-6 py-12 lg:py-20 space-y-24">
        {/* Hero & Upload */}
        <section className="space-y-10">
          <div className="text-center space-y-4 max-w-2xl mx-auto">
            <h2 className="text-4xl lg:text-5xl font-black tracking-tight leading-[1.1] text-white text-balance">Turn your images into <span className="text-transparent bg-clip-text bg-gradient-to-r from-violet-400 to-fuchsia-400">amazing prompts</span></h2>
            <p className="text-slate-400 text-lg lg:text-xl font-medium leading-relaxed text-balance">Upload your photos and our AI will create great prompts for you.</p>
          </div>

          <div 
            className={`relative group p-16 lg:p-24 border-2 border-dashed rounded-[2.5rem] text-center glass-card transition-all duration-500 cursor-pointer overflow-hidden premium-shadow ${isDragging ? 'border-violet-400 bg-violet-500/10 scale-[1.01] shadow-[0_0_50px_rgba(139,92,246,0.2)]' : 'border-white/10 hover:border-violet-500/40'} ${dropSuccess ? 'ring-4 ring-emerald-500/20 border-emerald-500/40 bg-emerald-500/5' : ''}`}
            onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); setIsDragging(true); }}
            onDragEnter={(e) => { e.preventDefault(); e.stopPropagation(); setIsDragging(true); }}
            onDragLeave={(e) => { e.preventDefault(); e.stopPropagation(); setIsDragging(false); }}
            onDrop={handleFileUpload}
            onClick={() => fileInputRef.current?.click()}
          >
            <div className={`absolute inset-0 bg-emerald-500/5 transition-opacity duration-300 pointer-events-none flex items-center justify-center z-20 ${dropSuccess ? 'opacity-100' : 'opacity-0'}`}>
               <Check size={80} className={`text-emerald-400 transition-transform duration-500 ${dropSuccess ? 'scale-110 opacity-100' : 'scale-0 opacity-0'}`} />
            </div>
            <div className="absolute inset-0 bg-gradient-to-b from-transparent to-violet-500/5 opacity-0 group-hover:opacity-100 transition-opacity" />
            <input ref={fileInputRef} type="file" multiple className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileUpload} accept="image/png, image/jpeg, image/jpg" />
            <div className={`relative z-10 space-y-6 transition-all duration-500 ${isDragging ? 'scale-95 blur-[1px] opacity-60' : 'scale-100'}`}>
              <div className="w-24 h-24 bg-gradient-to-tr from-violet-600/20 to-fuchsia-600/20 border border-white/10 rounded-3xl flex items-center justify-center mx-auto group-hover:scale-110 group-hover:rotate-3 transition-all duration-500"><Plus size={48} className="text-violet-400" /></div>
              <div className="space-y-2">
                <p className="text-2xl font-bold text-white tracking-tight">Drop your images here</p>
                <p className="text-slate-500 font-medium text-balance px-4">Drag files here or click Add Images to begin (Jpg, Jpeg & Png)</p>
              </div>
            </div>
          </div>

          {/* Status banner */}
          {hasImages && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 flex justify-center">
              <div className={`glass-card px-8 py-6 rounded-[2rem] flex items-center gap-4 premium-shadow border-emerald-500/20 bg-emerald-500/5`}>
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center bg-emerald-500/10 text-emerald-400`}>{allFinished ? <FileCheck size={24} /> : (isGenerating ? <Loader2 size={24} className="animate-spin" /> : <FileCheck size={24} />)}</div>
                <div>
                  <p className="text-lg font-black text-white tracking-tight">{isPaused ? `Paused at ${currentProcessingIndex}/${images.length}` : (allFinished ? `All ${images.length} images processed` : `${images.length} images in workspace`)}</p>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">{allFinished ? 'Tasks successfully completed' : 'Ready to forge or add more'}</p>
                </div>
                {!isGenerating && (
                  <button onClick={(e) => { e.stopPropagation(); clearImages(); }} className="ml-4 p-2.5 hover:bg-rose-500/20 text-slate-500 hover:text-rose-400 rounded-xl transition-all"><Trash2 size={18} /></button>
                )}
              </div>
            </div>
          )}

          {/* Processing Details */}
          {isGenerating && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-500 space-y-8 max-w-2xl mx-auto py-10 px-8 glass-card rounded-[2.5rem] border-violet-500/20 bg-violet-500/5">
              <div className="text-center space-y-3">
                <div className="w-16 h-16 bg-violet-500/10 rounded-full flex items-center justify-center mx-auto mb-4 border border-violet-500/20 relative"><Loader2 size={32} className="text-violet-400 animate-spin" /><div className="absolute -top-1 -right-1 w-4 h-4 bg-fuchsia-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(217,70,239,0.5)]" /></div>
                <h3 className="text-2xl font-black text-white tracking-tight">Forging Prompts...</h3>
                <p className="text-sm font-bold text-slate-500 uppercase tracking-[0.2em] animate-pulse">Running batch sequence...</p>
              </div>
              <div className="space-y-4">
                <div className="flex justify-between text-[10px] font-black text-slate-500 uppercase tracking-widest"><span>Current Task: {currentProcessingIndex + 1} of {images.length}</span><span>{Math.round(generationProgress)}% Complete</span></div>
                <div className="w-full h-4 bg-slate-950/50 rounded-full overflow-hidden p-1 border border-white/5"><div className="h-full bg-gradient-to-r from-violet-500 via-fuchsia-500 to-indigo-500 rounded-full transition-all duration-700" style={{ width: `${generationProgress}%` }} /></div>
              </div>
            </div>
          )}

          {/* Batch Completed card */}
          {allFinished && !isGenerating && !isPaused && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000 flex flex-col items-center gap-10">
              <div className="glass-card w-full max-w-2xl p-12 rounded-[3rem] border-fuchsia-500/20 bg-fuchsia-500/5 text-center space-y-6 premium-shadow relative overflow-hidden">
                <div className="absolute -top-10 -right-10 p-6 opacity-5 rotate-12 pointer-events-none"><Trophy size={180} /></div>
                <div className="w-20 h-20 bg-fuchsia-500/10 rounded-[2rem] flex items-center justify-center mx-auto mb-6 border border-fuchsia-500/20"><Check size={40} className="text-fuchsia-400" /></div>
                <div className="space-y-2">
                  <h3 className="text-3xl font-black text-white tracking-tight">Batch Completed</h3>
                  <p className="text-slate-400 font-medium text-lg text-balance">Export your prompts to CSV to view results.</p>
                </div>
                <div className="pt-6">
                  <button onClick={exportCSV} className="w-full py-6 px-12 rounded-[1.5rem] bg-white text-slate-950 hover:bg-slate-200 font-black text-xl transition-all flex items-center justify-center gap-4 premium-shadow active:scale-[0.98]"><Download size={28} className="text-fuchsia-600" />Download CSV List</button>
                </div>
              </div>
            </div>
          )}

          {!isGenerating && (
            <div className="flex flex-col sm:flex-row gap-5 max-w-2xl mx-auto">
              <button onClick={() => fileInputRef.current?.click()} className="flex-1 py-5 px-10 rounded-[1.5rem] bg-slate-900 hover:bg-slate-800 text-white font-black text-lg transition-all flex items-center justify-center gap-3 border border-white/10 hover:border-white/20 premium-shadow"><ImagePlus size={24} className="text-violet-400" />Add Images</button>
              <button onClick={generatePrompts} disabled={images.length === 0} className={`flex-1 py-5 px-10 rounded-[1.5rem] font-black text-lg shadow-2xl transition-all active:scale-[0.98] flex items-center justify-center gap-3 ${images.length === 0 ? 'bg-slate-900 text-slate-600 cursor-not-allowed border border-white/5' : 'bg-white text-slate-950 hover:bg-slate-200 premium-shadow'}`}>
                {isPaused ? <Play size={24} className="text-emerald-600" /> : <Sparkles size={24} className="text-violet-600" />}{isPaused ? 'Resume Processing' : 'Start Creating'}
              </button>
            </div>
          )}
        </section>

        {/* Refiner */}
        <section className="space-y-10 relative">
          <div className="absolute -top-24 -left-24 w-64 h-64 bg-fuchsia-500/10 blur-[100px] pointer-events-none" />
          <div className="flex items-center gap-4 mb-2"><div className="p-3 bg-fuchsia-500/10 rounded-2xl"><LayoutGrid size={24} className="text-fuchsia-400" /></div><div><h2 className="text-3xl font-black tracking-tight text-white">Prompt Improver</h2><p className="text-slate-500 font-medium">Make your prompt ideas look better.</p></div></div>
          <div className="glass-card rounded-[2.5rem] p-1.5 premium-shadow">
            <div className="p-8 lg:p-10 space-y-6">
              <textarea value={refineInput} onChange={(e) => setRefineInput(e.target.value)} placeholder="Paste your prompt ideas here..." className="w-full h-48 bg-slate-950/50 rounded-3xl p-8 text-lg text-slate-100 placeholder-slate-600 border border-white/5 focus:border-fuchsia-500/50 focus:ring-4 focus:ring-fuchsia-500/5 outline-none transition-all resize-none font-medium leading-relaxed" />
              <button onClick={refinePromptAction} disabled={isGenerating || !refineInput} className="w-full py-5 bg-gradient-to-r from-fuchsia-600 to-violet-600 hover:from-fuchsia-500 hover:to-violet-500 disabled:bg-slate-900 disabled:from-transparent disabled:to-transparent disabled:text-slate-700 text-white font-black text-lg rounded-[1.5rem] transition-all flex items-center justify-center gap-3 premium-shadow active:scale-[0.99]">{isGenerating ? <RotateCcw size={22} className="animate-spin" /> : <Sparkles size={22} />}Improve Prompt</button>
              {refineOutput && (
                <div className="mt-12 animate-in fade-in zoom-in-95 duration-500">
                  <div className="flex items-center justify-between mb-4"><span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">New Prompt</span><button onClick={() => copyToClipboard(refineOutput)} className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full text-xs font-bold text-slate-300 transition-all border border-white/5"><Copy size={14} />Copy</button></div>
                  <div className="p-10 bg-gradient-to-br from-violet-500/[0.08] to-fuchsia-500/[0.08] border border-white/5 rounded-3xl relative overflow-hidden"><div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none"><Sparkles size={120} /></div><p className="text-xl lg:text-2xl leading-[1.6] text-slate-100 font-semibold italic text-balance">"{refineOutput}"</p></div>
                </div>
              )}
            </div>
          </div>
        </section>

        {/* Logic Managers */}
        <section className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="space-y-6">
            <div className="flex items-center gap-3 px-2"><Layers size={20} className="text-indigo-400" /><h2 className="text-xl font-black text-white uppercase tracking-wider">Add to Start</h2></div>
