    reader.onerror = () => reject(new Error("FILE_READ_ERROR"));
    reader.onload = (e) => {
      const img = new Image();
      img.onerror = () => reject(new Error("IMAGE_LOAD_ERROR"));
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      if (provider === 'gemini' && typeof process !== 'undefined' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY);
      }
      throw new Error(`MISSING_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    let lastError = "";

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        const result = await this.retryTask(task, currentKey);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        lastError = error.message;
        console.warn(`[${provider}] Attempt with key ${currentIndex} failed: ${lastError}`);
        attempts++;
      }
    }

    throw new Error(`${provider.toUpperCase()}_PROVIDER_ERROR: ${lastError}`);
  }

  private static async retryTask(task: (key: string) => Promise<any>, key: string, retries = 3): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = (e.message || "").toLowerCase();

      // Stop retrying on terminal authentication errors
      if (err.includes("401") || err.includes("403") || err.includes("unauthorized") || err.includes("forbidden")) {
        throw e;
      }

      // If we have retries left, wait and try again
      if (retries > 0) {
        // Exponential backoff for retries
        const waitTime = Math.pow(2, 4 - retries) * 1000;
        await new Promise(r => setTimeout(r, waitTime));
        return this.retryTask(task, key, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    apiKey: string,
    modelId: string, 
    prompt: string, 
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const ai = new GoogleGenAI({ apiKey });
    const parts: any[] = [{ text: prompt }];
    if (base64Data && mimeType) {
      parts.unshift({
        inlineData: { mimeType, data: base64Data }
      });
    }

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { systemInstruction, temperature: 0.7, topP: 0.9 }
    });

    const text = response.text || "";
    if (!text.trim()) throw new Error("EMPTY_GEMINI_RESPONSE");
    return text;
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';

    let actualModelId = modelId;
    if (provider === 'groq') {
      // Reverting to -preview as -instant was reported not found in the latest error screenshot
      if (modelId === 'llama-4-scout-fast') actualModelId = 'llama-3.2-11b-vision-preview';
      else if (modelId === 'llama-4-maverick-hq') actualModelId = 'llama-3.2-90b-vision-preview';
    } else if (provider === 'mistral') {
      if (modelId === 'pixtral-12b-vision') actualModelId = 'pixtral-12b-2409';
    }

    const messages: any[] = [];
    if (systemInstruction) {
      messages.push({ role: 'system', content: systemInstruction });
    }

    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), 60000); // Increased timeout to 60s

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey.trim()}`
        },
        body: JSON.stringify({
          model: actualModelId,
          messages,
          temperature: 0.7,
          max_tokens: 1024,
          stream: false
        }),
        signal: controller.signal
      });

      clearTimeout(id);

      if (!response.ok) {
        const errText = await response.text();
        throw new Error(errText || `API Error ${response.status}`);
      }

      const data = await response.json();
      const content = data.choices?.[0]?.message?.content;
      if (!content || !content.trim()) throw new Error("EMPTY_PROVIDER_RESPONSE");
      return content;
    } catch (e: any) {
      clearTimeout(id);
      throw e;
    }
  }

  public static async generatePromptFromImage(
    image: PromptForgeImage,
    settings: Settings,
    model: Model
  ) {
    if (!model.hasVision) throw new Error("NON_VISION_MODEL");
    const { data, mime } = await prepareImage(image.file);

    const systemPrompt = `You are a high-end stock photography prompt engineer.
    Extract a detailed, descriptive prompt for this visual. 
    Output: ONE SINGLE English paragraph. Professional tone. No formatting symbols.
    ${settings.customInstruction ? `\nContext: ${settings.customInstruction}` : ''}`;

    const userPrompt = "Write a professional image prompt for this content.";

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, userPrompt, data, mime, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, userPrompt, data, mime, systemPrompt);
      }
    });
  }

  public static async refinePrompt(
    input: string,
    settings: Settings,
    model: Model
  ) {
    const systemPrompt = `Refine this user prompt into a professional, descriptive English paragraph. 
    Output: Single paragraph only. No symbols.
    ${settings.customInstruction ? `\nContext: ${settings.customInstruction}` : ''}`;

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, input, undefined, undefined, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, input, undefined, undefined, systemPrompt);
      }
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    return [];
  }
}

import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

/**
 * Optimized Image Processor
 * Reduces payload size by resizing and compressing images before sending to vision APIs.
 * Balanced for speed and detail extraction.
 */
const prepareImage = (file: File, maxDim: number = 800): Promise<{data: string, mime: string}> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("FILE_READ_ERROR"));
    reader.onload = (e) => {
      const img = new Image();
      img.onerror = () => reject(new Error("IMAGE_LOAD_ERROR"));
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        // Optimized for fast processing and small payload
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

