      if (modelId === 'pixtral-12b-vision') actualModelId = 'pixtral-12b-2409';
    } 
    // Groq: Use modelId exactly as provided in the UI (llama-4-scout-fast, llama-4-maverick-hq)
    // No fallbacks, no legacy mappings.

    return await this.performApiCall(baseUrl, apiKey, actualModelId, prompt, base64Data, mimeType, systemInstruction);
  }

  private static async performApiCall(
    baseUrl: string,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const messages: any[] = [];
    if (systemInstruction) {
      messages.push({ role: 'system', content: systemInstruction });
    }

    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), 20000); // Tighter 20s timeout for maximum speed

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey.trim()}`
        },
        body: JSON.stringify({
          model: modelId,
          messages,
          temperature: 0.2, 
          max_tokens: 1024,
          stream: false
        }),
        signal: controller.signal
      });

      clearTimeout(id);

      if (!response.ok) {
        const errText = await response.text();
        let errorData;
        try { errorData = JSON.parse(errText); } catch(e) { errorData = { error: { message: errText } }; }
        const message = errorData.error?.message || `API Error ${response.status}`;
        throw new Error(message);
      }

      const data = await response.json();
      const content = data.choices?.[0]?.message?.content;
      if (!content || !content.trim()) throw new Error("EMPTY_PROVIDER_RESPONSE");
      return content;
    } catch (e: any) {
      clearTimeout(id);
      throw e;
    }
  }

