import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

/**
 * Optimized Image Processor
 */
const prepareImage = (file: File, maxDim: number = 800): Promise<{data: string, mime: string}> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("FILE_READ_ERROR"));
    reader.onload = (e) => {
      const img = new Image();
      img.onerror = () => reject(new Error("IMAGE_LOAD_ERROR"));
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      if (provider === 'gemini' && typeof process !== 'undefined' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY, provider);
      }
      throw new Error(`MISSING_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    let lastError = "";

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        const result = await this.retryTask(task, currentKey, provider);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        lastError = error.message;
        attempts++;
      }
    }

    throw new Error(`${provider.toUpperCase()}_PROVIDER_ERROR: ${lastError}`);
  }

  private static async retryTask(task: (key: string) => Promise<any>, key: string, provider: Provider, retries = 5): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = (e.message || "").toLowerCase();

      // Stop retrying on terminal errors
      if (err.includes("401") || err.includes("403") || err.includes("invalid_api_key") || err.includes("decommissioned")) {
        throw e;
      }

      // Aggressive retry for transient network issues
      if (retries > 0) {
        const waitTime = provider === 'groq' ? 100 : 300;
        const delay = Math.max(waitTime, (6 - retries) * waitTime) + Math.random() * 150;
        await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, provider, retries - 1);
      }
      throw e;
    }
  }

