import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types';

/**
 * Optimized Image Processor
 */
const prepareImage = (file: File, maxDim: number = 1024): Promise<{data: string, mime: string}> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("FILE_READ_ERROR"));
    reader.onload = (e) => {
      const img = new Image();
      img.onerror = () => reject(new Error("IMAGE_LOAD_ERROR"));
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        resolve({
          data: dataUrl.split(',')[1],
          mime: 'image/jpeg'
        });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

const keyIndices: Record<Provider, number> = {
  gemini: 0,
  groq: 0,
  mistral: 0
};

export class AIService {
  private static async executeWithRotation(
    provider: Provider,
    keys: string[],
    task: (apiKey: string) => Promise<any>
  ): Promise<any> {
    if (!keys || keys.length === 0) {
      if (provider === 'gemini' && typeof process !== 'undefined' && process.env.API_KEY) {
        return await this.retryTask(task, process.env.API_KEY, provider);
      }
      throw new Error(`MISSING_KEYS_${provider.toUpperCase()}`);
    }

    const startIndex = keyIndices[provider];
    let attempts = 0;
    let lastError = "";

    while (attempts < keys.length) {
      const currentIndex = (startIndex + attempts) % keys.length;
      const currentKey = keys[currentIndex].trim();

      if (!currentKey) {
        attempts++;
        continue;
      }

      try {
        const result = await this.retryTask(task, currentKey, provider);
        keyIndices[provider] = currentIndex; 
        return result;
      } catch (error: any) {
        lastError = error.message;
        attempts++;
      }
    }

    throw new Error(`${provider.toUpperCase()}_PROVIDER_ERROR: ${lastError}`);
  }

  private static async retryTask(task: (key: string) => Promise<any>, key: string, provider: Provider, retries = 3): Promise<any> {
    try {
      return await task(key);
    } catch (e: any) {
      const err = (e.message || "").toLowerCase();

      // Stop retrying on terminal errors (Auth or specific Model Decommission errors)
      if (err.includes("401") || err.includes("403") || err.includes("invalid_api_key") || err.includes("does not exist") || err.includes("access")) {
        throw e;
      }

      // Aggressive retry for transient network issues
      if (retries > 0) {
        const waitTime = provider === 'groq' ? 300 : 800;
        const delay = waitTime * (4 - retries) + Math.random() * 200;
        await new Promise(r => setTimeout(r, delay));
        return this.retryTask(task, key, provider, retries - 1);
      }
      throw e;
    }
  }

  private static async geminiGenerate(
    apiKey: string,
    modelId: string, 
    prompt: string, 
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const ai = new GoogleGenAI({ apiKey });
    const parts: any[] = [{ text: prompt }];
    if (base64Data && mimeType) {
      parts.unshift({
        inlineData: { mimeType, data: base64Data }
      });
    }

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { systemInstruction, temperature: 0.4, topP: 0.9 }
    });

    const text = response.text || "";
    if (!text.trim()) throw new Error("EMPTY_GEMINI_RESPONSE");
    return text;
  }

  private static async providerGenerate(
    provider: Provider,
    apiKey: string,
    modelId: string,
    prompt: string,
    base64Data?: string,
    mimeType?: string,
    systemInstruction?: string
  ) {
    const baseUrl = provider === 'groq' ? 'https://api.groq.com/openai/v1' : 'https://api.mistral.ai/v1';

    // STRICT: Direct use of modelId from constants as per user requirement.
    let actualModelId = modelId;

    // Pixtral requires specific ID mapping due to naming differences in Mistral API vs documentation
    if (provider === 'mistral' && modelId === 'pixtral-12b-vision') {
      actualModelId = 'pixtral-12b-2409';
    }

    const messages: any[] = [];
    if (systemInstruction) {
      messages.push({ role: 'system', content: systemInstruction });
    }

    if (base64Data && mimeType) {
      messages.push({
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Data}` } }
        ]
      });
    } else {
      messages.push({ role: 'user', content: prompt });
    }

    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), 35000); // Increased timeout for heavier vision models

    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey.trim()}`
        },
        body: JSON.stringify({
          model: actualModelId,
          messages,
          temperature: 0.15,
          max_tokens: 1500,
          stream: false
        }),
        signal: controller.signal
      });

      clearTimeout(id);

      if (!response.ok) {
        const errText = await response.text();
        let errorData;
        try { errorData = JSON.parse(errText); } catch(e) { errorData = { error: { message: errText } }; }
        const message = errorData.error?.message || `API Error ${response.status}`;
        throw new Error(message);
      }

      const data = await response.json();
      const content = data.choices?.[0]?.message?.content;
      if (!content || !content.trim()) throw new Error("EMPTY_PROVIDER_RESPONSE");
      return content;
    } catch (e: any) {
      clearTimeout(id);
      throw e;
    }
  }

  public static async generatePromptFromImage(
    image: PromptForgeImage,
    settings: Settings,
    model: Model
  ) {
    if (!model.hasVision) throw new Error("NON_VISION_MODEL");
    const { data, mime } = await prepareImage(image.file, 1024);

    // Explicitly define custom instruction block to ensure models prioritize it
    const customInstructionBlock = settings.customInstruction 
      ? `\n\nUSER'S CUSTOM MANDATORY INSTRUCTION (PRIORITIZE THIS): "${settings.customInstruction}"\n`
      : "";

    const systemPrompt = `You are an expert AI image prompt engineer. Your job is to convert images into direct, ready-to-use prompts for an AI image generator.${customInstructionBlock}

    STRICT RULES:
    1. NO DESCRIPTIONS: Do not narrate or explain. Never use phrases like "The image is", "The image shows", "This photo has", or "I see".
    2. CONVERT TO PROMPT: Always convert the image into a direct image-generation prompt written as instructions for an image generator AI.
    3. START IMMEDIATELY: Start the prompt immediately with the subject and scene. Do not introduce or explain.
    4. SIMPLE ENGLISH: Use very simple English that a 10-year-old child can understand. Avoid complex words and long sentences.
    5. COMPLETE PROMPT: Output one complete, finished paragraph. Do not output unfinished, cut-off, or partial prompts.
    6. FULL VISUAL DETAIL: Describe the subject, pose, shape, style, colors, background, and mood clearly using simple words.
    7. NO MARKETING: Do not use words like "best", "perfect", "ideal", "amazing", or "high-quality".
    8. NO UNRELATED CONTENT: Only include what is actually visible in the image. Do not add unrelated objects or ideas.
    9. NO SYMBOLS: Do not use special characters or emojis unless they are actually part of the image.
    10. READY TO USE: The output must be a clean, ready-to-paste image generation prompt.
    ${settings.customInstruction ? `11. CUSTOM GUIDANCE: You MUST apply the user's specific request: "${settings.customInstruction}"` : ''}`;

    const userPrompt = "Convert this image into a direct, simple image generation prompt.";

    return await this.executeWithRotation(model.provider, settings.apiKeys[model.provider], async (key) => {
      if (model.provider === 'gemini') {
        return await this.geminiGenerate(key, model.id, userPrompt, data, mime, systemPrompt);
      } else {
        return await this.providerGenerate(model.provider, key, model.id, userPrompt, data, mime, systemPrompt);
      }
    });
  }

  public static async fetchModels(provider: Provider, apiKey: string): Promise<Model[]> {
    return [];
  }
}

