import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, 
  Trash2, 
  Download, 
  Settings as SettingsIcon, 
  RotateCcw, 
  MessageSquare, 
  Share2, 
  ChevronDown, 
  X, 
  Check, 
  AlertCircle,
  ExternalLink,
  Sparkles,
  Layers,
  Youtube,
  Users,
  User,
  ArrowRight,
  Mail,
  Phone,
  ImagePlus,
  Loader2,
  FileCheck,
