import { GoogleGenAI } from "@google/genai";
import { Provider, Model, PromptForgeImage, Settings } from '../types.ts';

const prepareImage = (file: File, maxDim: number = 1024): Promise<{data: string, mime: string}> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let { width, height } = img;
        if (width > height ? width > maxDim : height > maxDim) {
          const ratio = maxDim / Math.max(width, height);
          width *= ratio; height *= ratio;
        }
        canvas.width = width; canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
        }
        resolve({ data: canvas.toDataURL('image/jpeg', 0.8).split(',')[1], mime: 'image/jpeg' });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

export class AIService {
  public static async generatePromptFromImage(image: PromptForgeImage, settings: Settings, model: Model) {
    const { data, mime } = await prepareImage(image.file);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || settings.apiKeys[model.provider][0] });

    const systemPrompt = `You are a Carbon Copy Prompt Engineer. 
    1. START with "Create". 
    2. COMPLEXITY MATCH: If reference is SIMPLE/MINIMALIST (e.g. silhouette), output MUST stay simple. NO textures, NO shading.
    3. IDENTITY LOCK: Women stay women, eagles stay 1-headed. NO gender swaps. NO anatomical hallucinations.
    4. NO ARTIFACTS: No cutting lines or random shapes.
    5. LENGTH: 5+ lines. Use spatial/compositional descriptions of the simple shapes to reach length, NOT extra detail.
    6. ASCII ONLY.`;

    const response = await ai.models.generateContent({
      model: model.id,
      contents: { parts: [{ inlineData: { mimeType: mime, data } }, { text: "Recreate this image as a prompt. Mirror simplicity strictly." }] },
      config: { systemInstruction: systemPrompt, temperature: 0.1 }
    });

    return response.text || "";
  }
}

