        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'completed', prompt: result } : img));
      } catch (e) {
        setImages(prev => prev.map((img, idx) => idx === i ? { ...img, status: 'error', error: 'Failed' } : img));
      }
