${settings.customInstruction ? `- USER REQUEST: "${settings.customInstruction}"` : ''}
${activeNegativeWords.length > 0 ? `- EXCLUDE: ${activeNegativeWords.join(", ")}` : ''}`;

    const userPrompt = `Generate the final prompt now. Start with "Create". 
